window.C1_DATA={"course":{"title":"Deutsch C1","subtitle":"Türkçe → Almanca · Goethe C1 + telc C1 Hochschule","version":"c1-3"},"lessons":[{"id":1,"unit":"C1 temeli","title":"C1 düzeyi ve sınav stratejisi","skills":["Strateji","Okuma","Dinleme"],"goal":"C1 düzeyinde beklenen performansı ve Goethe/telc sınavlarının mantığını ayırt etmek.","explanation":"C1 artık günlük temel ifadeleri öğrenme düzeyi değildir. Amaç; uzun ve yoğun metinlerde örtük anlamı yakalamak, düşünceyi yapılandırmak, farklı kayıtları kullanmak, sözcük aramadan akıcı konuşmak ve karmaşık fikirleri gerekçelendirmektir. Bu kursta sözcük ezberinden çok bağlam, eşdizim, yeniden ifade etme, metin örgüsü ve üretim becerileri öne çıkar.","examples":[["Die Studie legt nahe, dass flexible Arbeitszeiten die Zufriedenheit erhöhen.","Çalışma, esnek çalışma saatlerinin memnuniyeti artırdığına işaret ediyor.","Kesin bir iddia yerine temkinli akademik ifade."],["Zwar ist die Maßnahme kostspielig, dennoch kann sie langfristig sinnvoll sein.","Önlem pahalı olsa da uzun vadede anlamlı olabilir.","Karşıt iki düşünceyi dengeli bağlama."]],"quiz":[{"q":"C1 düzeyinde hangi beceri özellikle önemlidir?","o":["Sadece temel kelimeleri ezberlemek","Örtük anlamı ve nüansı anlayıp karmaşık fikirleri yapılandırmak","Yalnızca kısa günlük diyaloglar kurmak"],"a":1,"why":"C1, karmaşık ve uzun metinler ile esnek, yapılandırılmış üretim gerektirir."},{"q":"Hangi çalışma yaklaşımı C1 için daha uygundur?","o":["Kelimeyi tek başına ezberlemek","Eşdizimleri, bağlamı ve yeniden ifade etmeyi birlikte çalışmak","Sadece fiil çekimi tablosu okumak"],"a":1,"why":"C1 sözvarlığı bağlamsal ve işlevsel olarak kullanılmalıdır."}]},{"id":2,"unit":"C1 temeli","title":"Metin örgüsü: gönderim ve bağdaşıklık","skills":["Okuma","Yazma"],"goal":"Uzun metinlerde zamir, gönderim ve bağlayıcıların neye işaret ettiğini izlemek.","explanation":"C1 okuma sorularında doğru cevap çoğu zaman tek bir cümlede değildir. “dies”, “dabei”, “dadurch”, “Letzteres”, “ein solcher Ansatz” gibi ifadeler önceki bilgiyi yeniden paketler. Yazarken de aynı ismi tekrar etmek yerine kontrollü gönderim kullanmak metni daha olgun gösterir.","examples":[["Viele Hochschulen führen hybride Formate ein. Dadurch können auch Berufstätige teilnehmen.","Birçok üniversite hibrit format getiriyor. Böylece çalışanlar da katılabiliyor.","“Dadurch” önceki eylemin sonucunu kurar."],["Es gibt zwei Modelle: Präsenzpflicht und freie Teilnahme. Letzteres bietet mehr Flexibilität.","İki model var: zorunlu yüz yüze ve serbest katılım. İkincisi daha fazla esneklik sunar.","“Letzteres” ikinci unsura gönderme yapar."]],"quiz":[{"q":"“Letzteres” hangi unsura gönderme yapar?","o":["İlk söylenene","Son söylenene","Bütün paragrafa"],"a":1,"why":"Letzteres = sonuncu / ikinci anılan unsur."},{"q":"“Dadurch” en sık hangi ilişkiyi kurar?","o":["Sonuç / araç","Zaman","Alıntı"],"a":0,"why":"Dadurch, önceki durumdan doğan sonucu veya aracı belirtir."}]},{"id":3,"unit":"C1 temeli","title":"Argümantasyon ve bağlaçlar","skills":["Yazma","Konuşma"],"goal":"Karşıtlık, neden, sonuç, taviz ve sınırlama ilişkilerini hassas biçimde kurmak.","explanation":"C1 metinlerinde “aber” ve “weil” tek başına yeterli değildir. İlişkiyi doğru türde kurmak gerekir: “zwar … jedoch”, “wenngleich”, “insofern als”, “folglich”, “demgegenüber”, “unter der Voraussetzung, dass”. Bağlaç çeşitliliği ancak anlam doğruysa puan getirir.","examples":[["Wenngleich die Datenbasis klein ist, sind die Ergebnisse bemerkenswert.","Veri tabanı küçük olmakla birlikte sonuçlar dikkat çekicidir.","Taviz ilişkisi."],["Die Nachfrage sank deutlich; folglich wurde das Angebot reduziert.","Talep belirgin biçimde düştü; bunun sonucunda arz azaltıldı.","Sonuç ilişkisi."]],"quiz":[{"q":"Hangi bağlaç taviz (concession) bildirir?","o":["folglich","wenngleich","infolgedessen"],"a":1,"why":"Wenngleich = her ne kadar / olsa da."},{"q":"“demgegenüber” en uygun hangi işlevdedir?","o":["Karşılaştırmalı karşıtlık","Sebep","Amaç"],"a":0,"why":"Demgegenüber iki görüş veya olguyu karşı karşıya getirir."}]},{"id":4,"unit":"C1 temeli","title":"Parafraz ve anlam inceliği","skills":["Okuma","Yazma"],"goal":"Aynı fikri farklı sözcük ve yapılarla, anlamı bozmadan yeniden ifade etmek.","explanation":"Goethe ve telc C1’de seçenekler metindeki ifadeyi çoğu zaman aynen tekrar etmez. “zurückgehen auf” ile “bedingt sein durch”, “in Betracht ziehen” ile “berücksichtigen”, “kaum zu überschätzen” ile “von großer Bedeutung sein” arasındaki ilişkiyi görmek gerekir. Üretimde de aynı sözcüğü tekrar etmek yerine kontrollü parafraz kullan.","examples":[["Der Rückgang ist auf mehrere Faktoren zurückzuführen.","Düşüş birden fazla faktöre bağlanabilir.","Nedensellik parafrazı."],["Diese Entwicklung darf nicht außer Acht gelassen werden.","Bu gelişme göz ardı edilmemelidir.","Resmî/akademik ifade."]],"quiz":[{"q":"“etwas in Betracht ziehen” en yakın hangi anlama gelir?","o":["etwas ablehnen","etwas berücksichtigen","etwas beweisen"],"a":1,"why":"Her ikisi de bir unsuru değerlendirmeye katmak demektir."},{"q":"“nicht außer Acht lassen” ne demektir?","o":["göz ardı etmemek","reddetmek","abartmak"],"a":0,"why":"Bir faktörü dikkate almaya devam etmek anlamındadır."}]},{"id":5,"unit":"C1 temeli","title":"Kayıt ve üslup: resmî, nötr, konuşma dili","skills":["Yazma","Konuşma"],"goal":"Duruma göre uygun kayıt seçmek ve üslup kırılmalarını önlemek.","explanation":"C1’de yalnızca doğru cümle kurmak değil, cümlenin bağlama uygun olması beklenir. Bir foruma “Meines Erachtens …” ile yazılabilir; yarı resmî e-postada “Ich möchte Sie darauf aufmerksam machen, dass …” uygundur. “Das ist total blöd” gibi ifadeler resmî bağlamda uygun değildir.","examples":[["Ich möchte Sie darauf aufmerksam machen, dass die vereinbarte Frist bereits abgelaufen ist.","Kararlaştırılan sürenin dolduğuna dikkatinizi çekmek isterim.","Yarı resmî/resmî."],["Aus meiner Sicht überwiegen die Vorteile.","Bana göre avantajlar ağır basıyor.","Nötr argümantatif kayıt."]],"quiz":[{"q":"Bir iş e-postasında en uygun ifade hangisidir?","o":["Das nervt echt.","Ich möchte Sie auf ein Problem aufmerksam machen.","Krass, das geht gar nicht."],"a":1,"why":"Duruma uygun, nazik ve açık bir kayıt kullanır."},{"q":"“Meines Erachtens” hangi işlevi görür?","o":["Görüş belirtme","Özür dileme","Alıntı yapma"],"a":0,"why":"Resmî/nötr biçimde kişisel görüş belirtir."}]},{"id":6,"unit":"C1 temeli","title":"Eşdizimler ve işlevsel fiil yapıları","skills":["Kelime","Yazma","Okuma"],"goal":"Tek tek kelime yerine doğal sözcük birliklerini ve akademik kalıpları kullanmak.","explanation":"C1’de sözcük bilgisi “çok kelime bilmekten” çok, doğru kelimeleri birlikte kullanabilmektir. “eine Entscheidung treffen”, “in Kraft treten”, “zur Verfügung stehen”, “Kritik üben”, “Maßnahmen ergreifen” gibi kalıplar doğal ve yoğun bir anlatım sağlar.","examples":[["Die Universität ergreift Maßnahmen gegen Prüfungsbetrug.","Üniversite sınav hilesine karşı önlemler alıyor.","“Maßnahmen ergreifen” sabit eşdizim."],["Die neue Regelung tritt im Januar in Kraft.","Yeni düzenleme ocakta yürürlüğe giriyor.","“in Kraft treten” sabit kalıp."]],"quiz":[{"q":"Doğal eşdizim hangisidir?","o":["eine Entscheidung machen","eine Entscheidung treffen","eine Entscheidung bauen"],"a":1,"why":"Standart Nomen-Verb-Verbindung “eine Entscheidung treffen”dir."},{"q":"“Kritik üben an” ne demektir?","o":["eleştirmek","desteklemek","erteleme yapmak"],"a":0,"why":"Bir konu veya kişiyi eleştirmek anlamındadır."}]},{"id":7,"unit":"C1 dilbilgisi","title":"Süreç edilgeni (Vorgangspassiv): süreç ve perspektif","skills":["Dilbilgisi","Yazma"],"goal":"Vorgangspassiv’i tüm temel zamanlarda ve farklı cümle türlerinde güvenli kullanmak.","explanation":"Vorgangspassiv “werden + Partizip II” ile bir sürece odaklanır. Fail gerekirse “von + Dativ” veya özellikle sebep/araç için “durch + Akkusativ” ile verilir. Perfektte “ist … worden” kullanılır; “geworden” değil.","examples":[["Die Ergebnisse werden morgen veröffentlicht.","Sonuçlar yarın yayımlanacak.","Präsens pasif."],["Die Daten sind mehrfach überprüft worden.","Veriler birkaç kez kontrol edildi.","Perfekt pasif."]],"quiz":[{"q":"Doğru Perfekt-Passiv hangisidir?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden."],"a":1,"why":"Vorgangspassiv Perfekt: sein + Partizip II + worden."},{"q":"“durch” en çok ne zaman uygundur?","o":["İnsan faili belirtirken her zaman","Nedensel/araçsal bir etkeni belirtirken","Zaman belirtirken"],"a":1,"why":"Örn. “durch einen Fehler verursacht”."}]},{"id":8,"unit":"C1 dilbilgisi","title":"Durum edilgeni (Zustandspassiv) ve öznesiz pasif","skills":["Dilbilgisi","Yazma"],"goal":"Sonuç durumu ile süreci ayırmak ve Akkusativobjekt olmadan pasif kurmak.","explanation":"Zustandspassiv “sein + Partizip II” ile ortaya çıkmış durumu anlatır: “Die Tür ist geschlossen.” Süreç “Die Tür wird geschlossen.” şeklindedir. Akkusativ nesnesi olmayan fiillerde de öznesiz pasif mümkündür: “Den Betroffenen wurde geholfen.”","examples":[["Der Antrag ist bereits genehmigt.","Başvuru hâlihazırda onaylanmış durumda.","Durum."],["Über den Vorschlag wurde lange diskutiert.","Öneri uzun süre tartışıldı.","Öznesiz Vorgangspassiv."]],"quiz":[{"q":"Hangisi Zustandspassiv’dir?","o":["Die Tür wird geschlossen.","Die Tür ist geschlossen.","Man schließt die Tür."],"a":1,"why":"sein + Partizip II sonuç durumunu gösterir."},{"q":"Doğru öznesiz pasif hangisidir?","o":["Den Gästen wurden geholfen.","Den Gästen wurde geholfen.","Die Gäste wurde geholfen."],"a":1,"why":"Gizli “es” nedeniyle fiil tekil kalır."}]},{"id":9,"unit":"C1 dilbilgisi","title":"İsim-fiil birleşimleri (Nomen-Verb-Verbindungen)","skills":["Dilbilgisi","Kelime"],"goal":"Serbest Nomen-Verb-Verbindungen ile Funktionsverbgefüge’yi tanımak ve kullanmak.","explanation":"C1’de birçok soyut eylem ad + fiil kalıbıyla ifade edilir. Bazıları gerçek anlamlıdır (“eine Frage stellen”), bazıları işlevsel fiil yapısıdır (“zur Sprache bringen”, “in Erwägung ziehen”). Bunlar özellikle resmî ve akademik metinlerde sık görülür.","examples":[["Der Vorschlag kam erneut zur Sprache.","Öneri tekrar gündeme geldi.","Funktionsverbgefüge."],["Wir ziehen eine Verlängerung der Frist in Erwägung.","Süre uzatımını değerlendiriyoruz.","Resmî ifade."]],"quiz":[{"q":"“in Erwägung ziehen” ne demektir?","o":["göz önünde bulundurmak","reddetmek","yasaklamak"],"a":0,"why":"Bir seçeneği ciddi biçimde değerlendirmeye almak."},{"q":"Doğal kalıp hangisidir?","o":["Kritik machen","Kritik üben","Kritik nehmen"],"a":1,"why":"Standart kalıp “Kritik üben (an + Dat.)”."}]},{"id":10,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): nesnel anlamlar","skills":["Dilbilgisi","Yazma"],"goal":"Zorunluluk, izin, olanak, istek ve görev anlamlarını doğru modal fiille aktarmak.","explanation":"Nesnel kullanımda modalite özne ve eyleme ilişkindir: “müssen” zorunluluk, “dürfen” izin/yasak, “können” yetenek/olanak, “sollen” görev/beklenti, “wollen” niyet bildirir. Perfektte Ersatzinfinitiv görülür: “hat teilnehmen können”.","examples":[["Die Teilnehmenden müssen sich vorher anmelden.","Katılımcılar önceden kayıt olmak zorunda.","Zorunluluk."],["Wir haben die Frist verlängern können.","Süreyi uzatabildik.","Ersatzinfinitiv."]],"quiz":[{"q":"“Es ist nicht notwendig” hangi modal yapıyla verilebilir?","o":["nicht müssen","nicht dürfen","sollen"],"a":0,"why":"nicht müssen = zorunlu olmamak; nicht dürfen = yasak olmak."},{"q":"Doğru Perfekt hangisidir?","o":["Wir haben kommen gekonnt.","Wir haben kommen können.","Wir sind kommen können."],"a":1,"why":"Modal fiilde Perfekt çoğunlukla Ersatzinfinitiv kullanır."}]},{"id":11,"unit":"C1 dilbilgisi","title":"Kip fiilleri (Modalverben): öznel anlam ve kanıt derecesi","skills":["Dilbilgisi","Okuma"],"goal":"Tahmin, çıkarım, söylenti ve şüpheli iddia gibi öznel modal anlamları çözmek.","explanation":"C1 metinlerinde modal fiiller kanıt derecesini kodlar. “muss” güçlü çıkarım, “dürfte” olası varsayım, “könnte” zayıf olasılık, “soll” başkasından duyulan bilgi, “will” konuşanın mesafeli yaklaştığı öz iddia anlamına gelebilir.","examples":[["Die Ursache dürfte im veränderten Konsumverhalten liegen.","Neden muhtemelen değişen tüketim davranışında yatıyor.","Olası varsayım."],["Der Minister soll von den Problemen gewusst haben.","Bakanın sorunları bildiği söyleniyor.","İkinci el bilgi/söylenti."]],"quiz":[{"q":"“Er soll davon gewusst haben.” en yakın anlam hangisidir?","o":["Kesin biliyorum.","Duyduğuma göre biliyormuş.","Bilmesi yasaktı."],"a":1,"why":"Öznel “sollen” doğrulanmamış/ikinci el bilgiyi aktarır."},{"q":"En güçlü çıkarım hangisidir?","o":["könnte","dürfte","muss"],"a":2,"why":"Öznel “müssen” konuşanın çok güçlü çıkarımını gösterir."}]},{"id":12,"unit":"C1 dilbilgisi","title":"Dilek/varsayım kipi (Konjunktiv II): varsayım, ihtiyat ve geçmiş pişmanlık","skills":["Dilbilgisi","Konuşma","Yazma"],"goal":"Gerçek dışı koşullar, temkinli ifadeler, öneriler ve geçmişte gerçekleşmeyen durumları ifade etmek.","explanation":"Konjunktiv II C1’de yalnızca “würde” cümlesi değildir. “Wäre die Nachfrage höher, ließe sich das Projekt finanzieren.” gibi yoğun yapılar, temkinli iddialar (“Es wäre denkbar, dass …”) ve geçmiş pişmanlık (“Man hätte früher reagieren müssen.”) önemlidir.","examples":[["Wäre mehr Zeit vorhanden, ließe sich die Analyse vertiefen.","Daha fazla zaman olsaydı analiz derinleştirilebilirdi.","İrreal koşul."],["Man hätte die Risiken früher berücksichtigen sollen.","Riskler daha erken dikkate alınmalıydı.","Geçmişe dönük değerlendirme."]],"quiz":[{"q":"Geçmişte gerçekleşmeyen öneri hangisidir?","o":["Man sollte reagieren.","Man hätte reagieren sollen.","Man soll reagieren."],"a":1,"why":"Konjunktiv II Vergangenheit geçmişe dönük tavsiye/eleştiri yapar."},{"q":"“Es wäre denkbar, dass …” ne tür bir işlev taşır?","o":["Temkinli varsayım","Kesin emir","Söylenti aktarma"],"a":0,"why":"İddiayı ihtiyatlılaştırır."}]},{"id":13,"unit":"C1 dilbilgisi","title":"Dolaylı anlatım kipi (Konjunktiv I)","skills":["Dilbilgisi","Okuma","Yazma"],"goal":"Başkasının sözünü mesafeli biçimde aktarmak ve haber dilini anlamak.","explanation":"Konjunktiv I, özellikle haber ve akademik aktarımda kaynağın sözünü konuşanın kendi iddiası gibi sunmamasını sağlar: “Die Autorin erklärt, die Daten seien eindeutig.” Biçim Indikativ ile çakışıyorsa çoğu zaman Konjunktiv II devreye girer.","examples":[["Der Forscher betont, die Ergebnisse seien vorläufig.","Araştırmacı sonuçların geçici olduğunu vurguluyor.","Dolaylı anlatım."],["Die Zeugen erklärten, sie hätten nichts bemerkt.","Tanıklar hiçbir şey fark etmediklerini söylediler.","Çakışmayı önlemek için Konjunktiv II."]],"quiz":[{"q":"Dolaylı anlatım için en tipik yapı hangisidir?","o":["Er sagt, er ist krank.","Er sagt, er sei krank.","Er sagt, krank sein."],"a":1,"why":"Konjunktiv I mesafeli aktarım sağlar."},{"q":"Konjunktiv I’in temel iletişim işlevi nedir?","o":["Kaynağın sözünü mesafeli aktarmak","Emir vermek","Gelecek zaman kurmak"],"a":0,"why":"Konuşan aktarılan bilgiye doğrudan sahiplik iddiası eklemez."}]},{"id":14,"unit":"C1 dilbilgisi","title":"Adlaştırma ve fiilleştirme","skills":["Dilbilgisi","Yazma","Okuma"],"goal":"Yoğun isim yapıları ile açık fiil cümleleri arasında dönüşüm yapmak.","explanation":"Akademik ve resmî metinler sık sık nominal yapı kullanır: “wegen der steigenden Kosten”. Daha akıcı anlatım için fiilleştirilebilir: “weil die Kosten steigen”. Ters yönde dönüşüm de metni yoğunlaştırır. Doğru edat ve hâl seçimi kritik önemdedir.","examples":[["Aufgrund der starken Nachfrage wurde das Angebot erweitert.","Yüksek talep nedeniyle teklif genişletildi.","Nominal yapı."],["Weil die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","Talep çok arttığı için teklif genişletildi.","Fiilleştirilmiş yapı."]],"quiz":[{"q":"“wegen der Verzögerung” için uygun fiil cümlesi hangisidir?","o":["weil sich etwas verzögert","obwohl sich etwas verzögert","damit sich etwas verzögert"],"a":0,"why":"“wegen” neden bildirir; “weil” ile fiilleştirilebilir."},{"q":"Nominalizasyonun tipik etkisi nedir?","o":["Metni yoğunlaştırır ve resmîleştirebilir","Her zaman konuşma dilini artırır","Fiil zamanını kaldırdığı için anlamı yok eder"],"a":0,"why":"Özellikle akademik/resmî yazıda bilgi yoğunluğunu artırır."}]},{"id":15,"unit":"Goethe C1 okuma","title":"Okuma Bölüm 1: kelimelerle metin rekonstrüksiyonu","skills":["Okuma","Kelime","Dilbilgisi"],"goal":"Yaklaşık 320 kelimelik bilgi metninde sekiz boşluğu leksik ve dilbilgisel ipuçlarıyla tamamlamak.","explanation":"Goethe Lesen Teil 1, dört seçenekli sekiz boşlukla sözcük bilgisi ve yapıları birlikte sınar. Önce tüm paragrafın işlevini belirle, sonra eşdizim, rektion, bağlaç ve gönderim kontrolü yap. Tek bir kelimenin Türkçe karşılığına göre karar verme.","examples":[["Die Maßnahme trägt dazu bei, den Energieverbrauch zu senken.","Önlem enerji tüketimini azaltmaya katkıda bulunur.","“dazu beitragen, zu …” kalıbı."],["Die Ergebnisse stehen im Einklang mit früheren Studien.","Sonuçlar önceki çalışmalarla uyumludur.","“im Einklang mit” eşdizimi."]],"quiz":[{"q":"“einen Beitrag ___ leisten” boşluğu nasıl tamamlanır?","o":["an","zu","von"],"a":1,"why":"“einen Beitrag zu etwas leisten”."},{"q":"Bu bölümde en güvenilir strateji hangisidir?","o":["Sadece boşluğun sağındaki kelimeye bakmak","Önce bağlam + eşdizim + dilbilgisi ilişkisini birlikte kontrol etmek","En uzun seçeneği seçmek"],"a":1,"why":"Soru hem leksik hem yapısal uyum gerektirir."}]},{"id":16,"unit":"Goethe C1 okuma","title":"Okuma Bölüm 2: bilgi yoğun makale","skills":["Okuma"],"goal":"Uzun bir makalede ana fikir, ayrıntı ve örtük tutumu yedi soruda ayırt etmek.","explanation":"Bu bölümde seçenekler metni parafraz eder. Önce sorudaki anahtar kavramı bul, metinde ilgili bölgeye git, sonra seçeneklerdeki kapsam farklarını kontrol et: “bazıları” ≠ “çoğu”, “neden” ≠ “sonuç”, “öneriyor” ≠ “kanıtlıyor”.","examples":[["Die Studie weist auf einen Zusammenhang hin.","Çalışma bir ilişkiye işaret ediyor.","“beweist” kadar güçlü değildir."],["Nur ein Teil der Befragten …","Katılımcıların yalnızca bir bölümü …","Kapsam sınırlıdır."]],"quiz":[{"q":"Metinde “weist darauf hin” yazıyorsa hangi seçenek aşırı güçlü olabilir?","o":["deutet an","beweist eindeutig","legt nahe"],"a":1,"why":"“beweisen” kanıt derecesini gereksiz yükseltir."},{"q":"Bu bölümde soruların sırası genelde neyi takip eder?","o":["Metnin kronolojik akışını","Alfabetik sırayı","Seçeneklerin uzunluğunu"],"a":0,"why":"Goethe formatında Teil 2 itemleri metin akışını takip eder."}]},{"id":17,"unit":"Goethe C1 okuma","title":"Okuma Bölüm 3: cümlelerle metin rekonstrüksiyonu","skills":["Okuma","Metin örgüsü"],"goal":"Eksik cümleleri mantıksal ve dilsel bağlarla doğru boşluklara yerleştirmek.","explanation":"Bir cümlenin uygunluğunu sadece konu benzerliği değil, önceki/sonraki cümleyle kurduğu köprü belirler. Artikel, zamir, zaman çizgisi, tema-rhema, neden-sonuç ve örnekleme işaretlerini birlikte kullan. İki cümle fazladır.","examples":[["Diese Entwicklung hat jedoch eine Kehrseite.","Bu gelişmenin yine de bir dezavantajı var.","Önceki olumlu gelişmeye gönderim yapar."],["Ein Beispiel dafür liefert die Verkehrsplanung.","Buna bir örnek ulaşım planlamasıdır.","“dafür” önceki genellemeye bağlanır."]],"quiz":[{"q":"Bir boşluğa “Ein Beispiel dafür …” geliyorsa önceki bağlamda ne beklenir?","o":["Genel bir iddia","Tamamen yeni konu","Selamlama"],"a":0,"why":"“dafür” önceki genellemeye gönderir ve örnek açar."},{"q":"En güçlü bağlayıcı ipucu hangilerinden biri olabilir?","o":["Gönderim zamiri ve artikel uyumu","Cümlenin uzun olması","Yazarın adı"],"a":0,"why":"Gönderim zinciri yerleştirmeyi doğrudan sınırlar."}]},{"id":18,"unit":"Goethe C1 okuma","title":"Okuma Bölüm 4: görüş ve ifade eşleştirme","skills":["Okuma","Nüans"],"goal":"Birden fazla metinde görüş, tavır ve ince farkları hızla bulmak.","explanation":"Teil 4’te aynı tema hakkında birden çok kısa katkı bulunur. Sorudaki ifadeyi metinde birebir arama; konuşmacının tutumunu eş anlamlı/parafraz biçimde yakala. Özellikle koşullar, sınırlamalar ve “yalnızca şu durumda” gibi nüanslara dikkat et.","examples":[["Ich halte die Idee grundsätzlich für sinnvoll, sofern …","Fikir bence temelde anlamlı, şu koşulla ki …","Koşullu destek."],["Davon bin ich keineswegs überzeugt.","Buna hiç ikna olmuş değilim.","Açık ret."]],"quiz":[{"q":"“grundsätzlich dafür, sofern …” nasıl bir tutumdur?","o":["Koşulsuz destek","Koşullu destek","Tam ret"],"a":1,"why":"“sofern” desteği bir koşula bağlar."},{"q":"Eşleştirme sorusunda en iyi yöntem nedir?","o":["Her metni kelime kelime çevirmek","Her konuşmacı için kısa tutum etiketi çıkarmak","Sadece ilk cümleyi okumak"],"a":1,"why":"Tutum etiketi seçenekleri hızla karşılaştırmayı kolaylaştırır."}]},{"id":19,"unit":"Goethe C1 okuma","title":"65 dakikayı yönetmek","skills":["Okuma","Strateji"],"goal":"30 item ve yaklaşık 2000 kelimelik modülde süreyi kontrollü dağıtmak.","explanation":"Resmî formatta Lesen 65 dakikadır. Önerilen dağılım kabaca Teil 1 için 10, Teil 2 için 20, Teil 3 için 20 ve Teil 4 için 10 dakika; kalan süre kontrol içindir. Zor bir itemde takılıp kalmak yerine işaret koyup dönmek daha verimlidir.","examples":[["Teil 1 → 10 Min.","Teil 1 → 10 dk.","Hızlı ama dikkatli rekonstrüksiyon."],["Kontrolle → ca. 5 Min.","Kontrol → yaklaşık 5 dk.","Cevap aktarımı ve kontrol."]],"quiz":[{"q":"Goethe C1 Lesen toplam süresi nedir?","o":["45 dakika","65 dakika","90 dakika"],"a":1,"why":"Modül 65 dakika ve 30 itemden oluşur."},{"q":"Bir soruda uzun süre takılırsan en iyi strateji?","o":["Tüm kalan süreyi ona harcamak","Geçici seçim yapıp işaretleyerek sonra dönmek","Sınavı bırakmak"],"a":1,"why":"Zaman yönetimi tüm 30 itemi görmeyi sağlar."}]},{"id":20,"unit":"Goethe C1 dinleme","title":"Dinleme Bölüm 1: üç içeriği eşleştirme","skills":["Dinleme","Nüans"],"goal":"Bir podcastte üç kitap/yayın/ürün hakkında verilen ayrıntıları altı ifadeyle eşleştirmek.","explanation":"Teil 1 yaklaşık 420 kelimelik bir podcasttir ve yalnızca bir kez dinlenir. Altı ifade üç içeriğe atanır. Dinlemeden önce 60 saniyede ifadelerdeki ayırt edici özellikleri işaretle; isimlerden çok özellikleri dinle.","examples":[["Im Mittelpunkt steht nicht das Ergebnis, sondern der Weg dorthin.","Odakta sonuç değil, ona giden süreç var.","Karşıt vurguyu yakala."],["Besonders überzeugend ist die Verbindung von Forschung und persönlicher Erfahrung.","Özellikle araştırma ile kişisel deneyimin birleşimi ikna edici.","Değerlendirme + özellik."]],"quiz":[{"q":"Teil 1 kaç kez dinlenir?","o":["Bir kez","İki kez","Üç kez"],"a":0,"why":"Goethe C1 Hören Teil 1 bir kez dinlenir."},{"q":"Dinlemeden önce hangi hazırlık daha etkilidir?","o":["İfadelerde ayırt edici anahtarları belirlemek","Tüm seçenekleri ezberlemek","Ses başlamadan cevap vermek"],"a":0,"why":"Bir defa dinlendiği için hedeflenen bilgiyi önceden bilmek önemlidir."}]},{"id":21,"unit":"Goethe C1 dinleme","title":"Dinleme Bölüm 2: uzman röportajı","skills":["Dinleme"],"goal":"Yaklaşık 620 kelimelik uzman röportajında ifade doğruluğu ve ayrıntıları değerlendirmek.","explanation":"Teil 2 iki kez dinlenir ve dokuz item içerir. “stimmt / stimmt nicht / dazu wird nichts gesagt” ayrımı özellikle önemlidir. Metinde benzer bir konu geçmesi, ifadenin gerçekten söylenmiş olduğu anlamına gelmez.","examples":[["Das Thema wird erwähnt, aber die konkrete Behauptung nicht bestätigt.","Konu geçiyor ama somut iddia doğrulanmıyor.","“dazu wird nichts gesagt” olabilir."],["Der Experte widerspricht der verbreiteten Annahme.","Uzman yaygın varsayıma karşı çıkıyor.","“stimmt nicht” için açık karşıtlık."]],"quiz":[{"q":"Bir konu metinde geçiyor ama sorudaki iddia net olarak doğrulanmıyorsa ne düşünmelisin?","o":["Her zaman stimmt","“dazu wird nichts gesagt” olasılığı","Her zaman stimmt nicht"],"a":1,"why":"İlgili konu ile somut iddia ayrılmalıdır."},{"q":"Teil 2 kaç kez dinlenir?","o":["Bir","İki","Dört"],"a":1,"why":"Uzman röportajı iki kez dinlenir."}]},{"id":22,"unit":"Goethe C1 dinleme","title":"Dinleme Bölüm 3: çok katılımcılı tartışma","skills":["Dinleme","Konuşmacı takibi"],"goal":"Dört bölümde üç konuşmacının görüşlerini ve ayrıntılarını bir kez dinleyerek izlemek.","explanation":"Teil 3 yaklaşık 710 kelimelik bir tartışmadır, dört parçaya bölünür ve her parça bir kez dinlenir. Her bölümden önce iki soruya bakmak için 30 saniye vardır. Konuşmacıları A/B/C olarak not alıp tutumlarını kısa sözcüklerle etiketlemek karışıklığı azaltır.","examples":[["Moderator: Thema eröffnet – Expertin A: skeptisch – Experte B: pragmatisch.","Moderatör konuyu açıyor – A şüpheci – B pragmatik.","Konuşmacı haritası."],["Das sehe ich anders.","Ben bunu farklı görüyorum.","Tutum değişimi sinyali."]],"quiz":[{"q":"Teil 3 nasıl dinlenir?","o":["Tüm metin iki kez","Dört bölüm, her biri bir kez","Sekiz kısa metin üç kez"],"a":1,"why":"Her bölüm bir kez dinlenir; her bölüm için iki item vardır."},{"q":"Konuşmacıları ayırmak için ne yapabilirsin?","o":["İsim/rol + 1-2 kelimelik tutum notu","Tam cümleleri yazmak","Sadece son konuşmacıyı takip etmek"],"a":0,"why":"Kısa konuşmacı haritası bilişsel yükü azaltır."}]},{"id":23,"unit":"Goethe C1 dinleme","title":"Dinleme Bölüm 4: konferans/sunum","skills":["Dinleme","Not alma"],"goal":"Yaklaşık 540 kelimelik bir sunumda ana yapı ve yedi ayrıntıyı iki dinlemede yakalamak.","explanation":"Teil 4 iki kez dinlenen bir Vortrag’tır. Önceden 90 saniyede yedi soruyu okumak gerekir. İlk dinlemede yapı ve ana iddiaları, ikinci dinlemede sayılar, koşullar, neden-sonuç ve sınırlamaları tamamla.","examples":[["Zunächst … anschließend … abschließend …","Önce … ardından … sonuç olarak …","Sunum iskeletini gösterir."],["Entscheidend ist dabei nicht X, sondern Y.","Burada belirleyici olan X değil Y’dir.","Sınavda sık sorulan vurgu."]],"quiz":[{"q":"Teil 4 kaç kez dinlenir?","o":["Bir","İki","Üç"],"a":1,"why":"Vortrag iki kez dinlenir."},{"q":"İlk dinlemede öncelik ne olmalı?","o":["Her kelimeyi yazmak","Sunumun iskeleti ve ana iddialar","Sadece sayılar"],"a":1,"why":"İkinci dinlemede ayrıntılar tamamlanabilir."}]},{"id":24,"unit":"Dinleme stratejisi","title":"Not alma, parafraz ve implizit tutum","skills":["Dinleme","Yazma"],"goal":"Uzun dinlemelerde anahtar notlar çıkarmak ve örtük değerlendirmeleri fark etmek.","explanation":"C1’de not, tam cümle değildir. “Problem → Ursache → Folge → Lösung” gibi bir şema, isim + fiil + sayı kombinasyonları ve konuşmacı tutum etiketleri daha işlevseldir. Tonlamayı ve “allerdings”, “durchaus”, “keineswegs” gibi tutum işaretlerini dinle.","examples":[["Kosten ↑ → Teilnahme ↓","Maliyet artıyor → katılım düşüyor","Kısa nedensel not."],["durchaus sinnvoll, aber nur wenn …","gayet anlamlı, ama yalnızca şu durumda …","Koşullu olumlu tutum."]],"quiz":[{"q":"Etkili C1 notu hangisidir?","o":["Tüm cümleyi kelimesi kelimesine yazmak","“Kosten ↑ → Nachfrage ↓” gibi ilişki notu","Hiç not almamak"],"a":1,"why":"Kısa ilişki notları dinlemeyi bölmez."},{"q":"“keineswegs” hangi sinyali verir?","o":["Güçlü olumsuzlama","Zaman sırası","Örnekleme"],"a":0,"why":"“Hiçbir şekilde / kesinlikle değil” anlamında tutum işaretidir."}]},{"id":25,"unit":"Goethe C1 yazma","title":"Yazma Bölüm 1: forumda görüş yazısı","skills":["Yazma","Argümantasyon"],"goal":"Yaklaşık 230 kelimelik yapılandırılmış bir forum katkısında dört dil işlevini gerçekleştirmek.","explanation":"Goethe Schreiben Teil 1 serbest bir forum metnidir. Yaklaşık 230 kelimede dört içerik/dil işlevini yerine getirmen gerekir: örneğin açıklamak, gerekçelendirmek, örnek vermek ve değerlendirmek. Puanlama görev tamamlama, kohärenz, sözcük dağarcığı ve yapılara bakar.","examples":[["Zunächst ist zu klären, was unter … zu verstehen ist.","Önce … ile ne kastedildiği açıklanmalı.","Giriş/çerçeveleme."],["Dem lässt sich entgegenhalten, dass …","Buna karşı şu söylenebilir ki …","Karşı argüman."]],"quiz":[{"q":"Teil 1 için hedef uzunluk yaklaşık nedir?","o":["80 kelime","230 kelime","500 kelime"],"a":1,"why":"Goethe C1 model formatı yaklaşık 230 kelime ister."},{"q":"Puanlamada hangisi kriterdir?","o":["Sadece yazım hatası sayısı","Görev tamamlama, kohärenz, kelime ve yapılar","El yazısının güzelliği"],"a":1,"why":"Dört temel kriter vardır."}]},{"id":26,"unit":"Goethe C1 yazma","title":"Yazma Bölüm 2: yarı resmî e-posta","skills":["Yazma","Kayıt"],"goal":"Yaklaşık 120 kelimelik e-postada sorun, açıklama, öneri ve nezaket işlevlerini uygun kayıtla yerine getirmek.","explanation":"Teil 2 daha kısa olsa da register daha hassastır. Muhatabı ve amacı netleştir; sorunu somutlaştır; uygulanabilir öneri getir; nazik ama belirsiz olmayan bir kapanış yap. Dört işlevin her biri görünür olmalıdır.","examples":[["Ich möchte Sie darauf aufmerksam machen, dass …","… konusuna dikkatinizi çekmek isterim.","Sorunu nazikçe açma."],["Als mögliche Lösung schlage ich vor, …","Olası çözüm olarak … öneriyorum.","Öneri işlevi."]],"quiz":[{"q":"Teil 2 hedef uzunluk yaklaşık nedir?","o":["120 kelime","230 kelime","30 kelime"],"a":0,"why":"Model formatta yaklaşık 120 kelime."},{"q":"Yarı resmî e-postada hangisi uygundur?","o":["Ey, das geht so nicht!","Ich wäre Ihnen dankbar, wenn …","LOL, bitte fixen."],"a":1,"why":"Nazik ve durum uygun bir kayıt kullanır."}]},{"id":27,"unit":"Goethe C1 konuşma","title":"Konuşma Bölüm 1: 5 dakikalık sunum","skills":["Konuşma","Sunum"],"goal":"İki konudan birini seçip dört noktayı kapsayan, yaklaşık 5 dakikalık yapılandırılmış Vortrag sunmak.","explanation":"Sunumda giriş, açık yapı, örnek/gerekçe, kendi görüşün ve sonuç bulunmalı. Ardından yaklaşık 2 dakikalık soru-cevap gelir. Ezberlenmiş metin gibi okumak yerine notlardan serbest konuş.","examples":[["Ich möchte zunächst die Ausgangslage skizzieren und anschließend zwei Aspekte gegenüberstellen.","Önce başlangıç durumunu çizeceğim, ardından iki yönü karşılaştıracağım.","Yol haritası."],["Damit komme ich zu meinem abschließenden Punkt.","Böylece son noktama geliyorum.","Geçiş."]],"quiz":[{"q":"Vortrag yaklaşık ne kadar sürer?","o":["1 dakika","5 dakika + sorular","15 dakika tek başına"],"a":1,"why":"Yaklaşık 5 dakikalık sunum, ardından soru-cevap."},{"q":"En iyi sunum notu hangisidir?","o":["Tam ezber metni","Başlık + 3-5 anahtar sözcük + örnek","Hiç yapı olmadan konuşmak"],"a":1,"why":"Serbest ama yapılandırılmış konuşmayı destekler."}]},{"id":28,"unit":"Goethe C1 konuşma","title":"Konuşma Bölüm 2: tartışma ve etkileşim","skills":["Konuşma","Etkileşim"],"goal":"Tartışmalı bir konuda görüş belirtmek, partnerin argümanına tepki vermek ve gerektiğinde ortak sonuç üretmek.","explanation":"C1 tartışma tek kişilik mini sunum değildir. Karşı tarafın argümanını alıp geliştirmek, itiraz etmek, netleştirme istemek ve sözü doğal biçimde devretmek gerekir. Yaklaşık 5 dakika sürer.","examples":[["Den Punkt verstehe ich, allerdings würde ich stärker gewichten, dass …","Noktayı anlıyorum, ancak ben … unsuruna daha fazla ağırlık verirdim.","Kibar itiraz."],["Können wir uns darauf einigen, dass …?","… konusunda anlaşabilir miyiz?","Ortak sonuç."]],"quiz":[{"q":"C1 tartışmada ne ayrıca değerlendirilir?","o":["Etkileşim ve reaksiyon","Sadece kelime sayısı","Yalnızca telaffuz"],"a":0,"why":"Partneradäquat etkileşim temel kriterdir."},{"q":"Partnerin fikrine katılmıyorsan en uygun başlangıç?","o":["Das ist Unsinn.","Ich sehe den Punkt, würde aber einwenden, dass …","Nein."],"a":1,"why":"C1 düzeyinde dengeli ve etkileşimli itiraz."}]},{"id":29,"unit":"telc C1 Hochschule","title":"Akademik özetleme ve bilgi aktarımı","skills":["Okuma","Dinleme","Yazma","Konuşma"],"goal":"Üniversite bağlamında sunum izlemek, ana bilgiyi yazılı aktarmak ve partner sunumunu özetlemek.","explanation":"telc Deutsch C1 Hochschule akademik bağlama daha güçlü odaklanır. Özellikle dinlemede bilgi transferi, yazmada erörterung/stellungnahme, konuşmada sunumun ardından partnerin içeriğini özetleme ve Anschlussfragen önemlidir. Bu nedenle kursun bu bölümünde “duyduğunu yeniden yapılandırma” aktif olarak çalışılır.","examples":[["Die Referentin führt drei Gründe an: …","Konuşmacı üç neden sunuyor: …","Özet başlangıcı."],["Wenn ich Sie richtig verstanden habe, sehen Sie das Hauptproblem in …","Sizi doğru anladıysam temel sorunu … olarak görüyorsunuz.","Partner sunumunu özetleme + doğrulama."]],"quiz":[{"q":"telc C1 Hochschule konuşmada Goethe’den özellikle hangi ek beceri öne çıkar?","o":["Partner sunumunu özetleme ve devam soruları","Alfabe söyleme","Form doldurma"],"a":0,"why":"Teil 1B doğrudan Zusammenfassung/Anschlussfragen içerir."},{"q":"telc Hören Teil 3’ün temel işlevi nedir?","o":["Bilgi transferi/not alma","Sadece doğru-yanlış","Kısa selamlaşma"],"a":0,"why":"Uzun Vortrag/Vorlesung’dan merkezi bilgiyi yazılı aktarma."}]},{"id":30,"unit":"Sınav hazırlığı","title":"Deneme sınavı, hata analizi ve hazır olma","skills":["Strateji","Tüm beceriler"],"goal":"Tam sınav simülasyonlarını süreli çözmek ve hataları türe göre analiz etmek.","explanation":"Son aşamada amaç yeni konu öğrenmek değil, performansı istikrarlı hâle getirmektir. Her yanlış cevabı “kelime”, “gönderim”, “çıkarım”, “dikkat”, “zaman” gibi bir nedene bağla. Yazma ve konuşmada A–E rubriğiyle kendini değerlendir; birkaç denemede 60 puan eşiğinin üstünde istikrarlı kalmaya çalış.","examples":[["Fehler: falsche Option wegen zu starker Aussage → Kategorie: Nuance.","Hata: aşırı güçlü seçeneği seçtim → kategori: nüans.","Hata günlüğü."],["Ziel: mindestens 18/30 in Lesen und Hören.","Hedef: Lesen ve Hören’de en az 18/30.","Goethe geçme eşiği."]],"quiz":[{"q":"Goethe Lesen/Hören modülünü geçmek için en az kaç doğru gerekir?","o":["15/30","18/30","24/30"],"a":1,"why":"Geçme sınırı %60 = 18/30."},{"q":"Deneme sonrası en yararlı analiz hangisidir?","o":["Sadece puana bakmak","Her hatanın nedenini sınıflandırmak","Yanlışları silmek"],"a":1,"why":"Hata türü sonraki çalışmayı yönlendirir."}]}],"grammarSets":[{"id":"passiv","title":"Edilgen yapı (Passiv)","subtitle":"Süreç, durum ve öznesiz edilgen yapı","questions":[{"q":"Die Kommission ___ den Antrag gestern ___.","o":["hat / abgelehnt","ist / abgelehnt worden","wurde / abgelehnt worden","war / ablehnen"],"a":1,"why":"Perfekt Vorgangspassiv: ist + Partizip II + worden."},{"q":"Aktiv: Man diskutiert über die Folgen. Doğru Passiv?","o":["Die Folgen werden diskutiert über.","Über die Folgen wird diskutiert.","Über die Folgen werden diskutiert.","Es diskutiert über die Folgen."],"a":1,"why":"Akkusativ nesnesi olmadığı için öznesiz pasif; fiil tekil."},{"q":"“Die Tür ist geschlossen.” neyi vurgular?","o":["Kapanma sürecini","Ortaya çıkmış durumu","Failin kim olduğunu","Geleceği"],"a":1,"why":"sein + Partizip II = Zustandspassiv."},{"q":"Das Gebäude wurde ___ ein Erdbeben beschädigt.","o":["von","durch","mit","bei"],"a":1,"why":"Nedensel/araçsal etken için “durch + Akk.” uygundur."},{"q":"Welche Form ist korrekt?","o":["Die Daten sind geprüft geworden.","Die Daten sind geprüft worden.","Die Daten haben geprüft worden.","Die Daten wurden geprüft gewesen."],"a":1,"why":"Perfekt Passiv’te “worden” kullanılır."},{"q":"Niemand hat eine Lösung gefunden. →","o":["Keine Lösung ist gefunden.","Es wurde keine Lösung gefunden.","Keine Lösung wurde finden.","Niemand wurde eine Lösung gefunden."],"a":1,"why":"Niemand çoğu zaman pasifte olumsuzlukla ifade edilir."},{"q":"Der Antrag ___ bereits genehmigt; wir warten nur auf die Zustellung.","o":["wird","ist","wurde gerade","würde"],"a":1,"why":"Burada sonuç durumu vurgulanıyor."},{"q":"Man half den Betroffenen sofort. →","o":["Die Betroffenen wurden sofort geholfen.","Den Betroffenen wurde sofort geholfen.","Den Betroffenen wurden sofort geholfen.","Es wurden die Betroffenen geholfen."],"a":1,"why":"helfen Dativ alır; öznesiz pasif tekil “wurde”."}]},{"id":"nvv","title":"İsim-fiil birleşimleri","subtitle":"Nomen-Verb-Verbindungen ve işlevsel fiil yapıları","questions":[{"q":"eine Entscheidung ___","o":["machen","treffen","tun","setzen"],"a":1,"why":"Standart eşdizim: eine Entscheidung treffen."},{"q":"Kritik ___ an der Reform","o":["üben","machen","stellen","geben"],"a":0,"why":"Kritik an etwas üben."},{"q":"etwas in Erwägung ___","o":["bringen","ziehen","nehmen","führen"],"a":1,"why":"in Erwägung ziehen = değerlendirmek."},{"q":"zur Verfügung ___","o":["sein/stehen","machen","ziehen","setzen"],"a":0,"why":"zur Verfügung stehen / stellen."},{"q":"in Kraft ___","o":["kommen","treten","gehen","laufen"],"a":1,"why":"in Kraft treten = yürürlüğe girmek."},{"q":"Maßnahmen ___","o":["ergreifen","nehmen","leisten","stellen"],"a":0,"why":"Maßnahmen ergreifen = önlem almak."},{"q":"eine Frage zur Sprache ___","o":["bringen","ziehen","treffen","halten"],"a":0,"why":"zur Sprache bringen = gündeme getirmek."},{"q":"einen Beitrag zu etwas ___","o":["leisten","machen","setzen","führen"],"a":0,"why":"einen Beitrag leisten."}]},{"id":"modal_obj","title":"Kip fiilleri – nesnel kullanım","subtitle":"Modalverben: zorunluluk, izin, olasılık ve niyet","questions":[{"q":"Du ___ hier nicht parken. Es ist verboten.","o":["musst","darfst","kannst","sollst"],"a":1,"why":"nicht dürfen = yasak."},{"q":"Wir ___ die Frist nicht einhalten; es war unmöglich.","o":["durften","konnten","sollten","wollten"],"a":1,"why":"nicht können = olanaksız/yetersiz olmak."},{"q":"Es ist nicht notwendig, dass du kommst. → Du ___ kommen.","o":["darfst nicht","musst nicht","sollst nicht","willst nicht"],"a":1,"why":"nicht müssen = zorunda olmamak."},{"q":"Perfekt: Wir ___ früher abreisen ___.","o":["haben / müssen","sind / gemusst","haben / gemusst","wurden / müssen"],"a":0,"why":"Ersatzinfinitiv: haben + Infinitiv + Modalinfinitiv."},{"q":"Man erwartet von uns, dass wir den Bericht überarbeiten. → Wir ___ den Bericht überarbeiten.","o":["sollen","dürfen","mögen","können"],"a":0,"why":"sollen görev/beklenti aktarır."},{"q":"Er weigert sich zu unterschreiben. → Er ___ nicht unterschreiben.","o":["will","darf","kann","muss"],"a":0,"why":"nicht wollen = isteksizlik/ret."},{"q":"Die Genehmigung erlaubt uns die Nutzung. → Wir ___ das Gebäude nutzen.","o":["dürfen","müssen","sollen","wollen"],"a":0,"why":"dürfen = izin."},{"q":"Sie ist fähig, komplexe Daten zu analysieren. → Sie ___ komplexe Daten analysieren.","o":["soll","kann","darf","muss"],"a":1,"why":"können = yetenek."}]},{"id":"modal_subj","title":"Kip fiilleri – öznel kullanım","subtitle":"Modalverben: tahmin, çıkarım, söylenti ve mesafe","questions":[{"q":"Er ___ schon angekommen sein; sein Auto steht draußen. (çok güçlü çıkarım)","o":["könnte","muss","soll","will"],"a":1,"why":"subjektives müssen = güçlü çıkarım."},{"q":"Die Preise ___ nächstes Jahr leicht sinken. (olasılık)","o":["könnten","müssen","wollen","sollen"],"a":0,"why":"könnte = belirsiz olasılık."},{"q":"Die Ministerin ___ bereits informiert gewesen sein. (duyuma göre)","o":["muss","soll","will","darf"],"a":1,"why":"sollen = ikinci el/doğrulanmamış bilgi."},{"q":"Der Zeuge ___ alles gesehen haben. (kendisi iddia ediyor, konuşan mesafeli)","o":["will","muss","darf","soll"],"a":0,"why":"wollen subjektiv = kişinin kendi iddiası, konuşan şüpheci olabilir."},{"q":"Die Ursache ___ in der neuen Software liegen. (muhtemelen)","o":["dürfte","soll","will","muss immer"],"a":0,"why":"dürfte = yüksek olasılık/varsayım."},{"q":"Das ___ kein Zufall sein. (güçlü olumsuz çıkarım)","o":["kann","muss","soll","darf"],"a":0,"why":"“Das kann kein … sein” = kesinlikle olamaz."},{"q":"Vergangenheit: Vielleicht hat er den Termin vergessen. → Er ___ den Termin vergessen haben.","o":["könnte","soll","will","muss"],"a":0,"why":"könnte + Infinitiv Perfekt."},{"q":"Rat: Du ___ deine Argumente klarer strukturieren.","o":["solltest","willst","darfst","kannst nur"],"a":0,"why":"Konjunktiv II von sollen = tavsiye."}]},{"id":"k2","title":"Dilek/varsayım kipi (Konjunktiv II)","subtitle":"Konjunktiv II ile gerçek dışılık, ihtiyat ve tavsiye","questions":[{"q":"___ mehr Daten vorhanden, ließe sich die Hypothese besser prüfen.","o":["Wären","Sind","Seien","Wurden"],"a":0,"why":"İrreal koşul: Wären …, ließe …"},{"q":"Geçmiş pişmanlık: Wir ___ früher reagieren ___.","o":["hätten / sollen","würden / sollen","seien / sollen","haben / sollen"],"a":0,"why":"hätten + Infinitiv + sollen."},{"q":"Temkinli öneri hangisidir?","o":["Das ist so.","Es wäre denkbar, dass …","Das muss so sein.","Mach das!"],"a":1,"why":"Konjunktiv II iddiayı yumuşatır."},{"q":"Wenn ich mehr Zeit ___, ___ ich den Bericht überarbeiten.","o":["hätte / würde","habe / werde","sei / würde","hatte / würde"],"a":0,"why":"İrreal şart."},{"q":"Es ___ sinnvoll, die Stichprobe zu vergrößern.","o":["wäre","sei","wird","war immer"],"a":0,"why":"Temkinli değerlendirme."},{"q":"Er tut so, als ___ er alles.","o":["wüsste","weiß","wisse","wusste immer"],"a":0,"why":"als ob/als + Konjunktiv II irreal karşılaştırma."},{"q":"Das ___ ich an deiner Stelle vermeiden.","o":["würde","werde","sei","habe"],"a":0,"why":"Tavsiye için Konjunktiv II."},{"q":"Hätten wir die Warnung ernst genommen, ___ es nicht so weit gekommen.","o":["wäre","ist","sei","würde jetzt"],"a":0,"why":"Geçmiş irreal koşul: wäre … gekommen."}]},{"id":"k1","title":"Dolaylı anlatım kipi (Konjunktiv I)","subtitle":"Konjunktiv I ile dolaylı anlatım ve kaynak mesafesi","questions":[{"q":"Die Autorin sagt, die Daten ___ eindeutig.","o":["seien","sind","wären nur","werden gewesen"],"a":0,"why":"Konjunktiv I plural: seien."},{"q":"Er erklärt, er ___ keine Kenntnis davon.","o":["habe","hat","hätte immer","haben"],"a":0,"why":"Konjunktiv I: habe."},{"q":"Der Sprecher behauptet, die Maßnahme ___ Wirkung.","o":["zeige","zeigt","zeigte zwingend","würde gezeigt"],"a":0,"why":"Konjunktiv I: zeige."},{"q":"Indikativ ve Konjunktiv I çakışırsa sık kullanılan çözüm?","o":["Konjunktiv II","Imperativ","Passiv zorunlu","Futur II"],"a":0,"why":"Mesafeyi görünür kılmak için Ersatzkonjunktiv II."},{"q":"Sie sagten, sie ___ nichts bemerkt.","o":["hätten","haben","seien bemerken","würden bemerkt"],"a":0,"why":"Plural biçimde Konjunktiv I “haben” ile çakıştığı için “hätten”."},{"q":"Konjunktiv I’in temel amacı?","o":["Kaynağı mesafeli aktarmak","Geleceği kesinleştirmek","Emir vermek","Soru sormak"],"a":0,"why":"Özellikle haber/rapor dilinde aktarım işlevi."},{"q":"Die Expertin betont, man ___ die Daten vorsichtig interpretieren.","o":["müsse","muss","musste","würde müssen gewesen"],"a":0,"why":"Konjunktiv I von müssen: müsse."},{"q":"Er meint, das Ergebnis ___ überraschend.","o":["sei","ist","wäre nur vielleicht","war"],"a":0,"why":"Konjunktiv I von sein: sei."}]},{"id":"nom","title":"Adlaştırma / fiilleştirme","subtitle":"Nominalisierung / Verbalisierung: yoğun akademik yapı ↔ açık fiil cümlesi","questions":[{"q":"“wegen der steigenden Kosten” →","o":["weil die Kosten steigen","obwohl die Kosten steigen","damit die Kosten steigen","wenn die Kosten nicht steigen"],"a":0,"why":"wegen = neden."},{"q":"“trotz der Kritik” →","o":["obwohl es Kritik gibt","weil es Kritik gibt","damit es Kritik gibt","bevor es Kritik gibt"],"a":0,"why":"trotz = taviz, obwohl."},{"q":"“nach Abschluss der Studie” →","o":["nachdem die Studie abgeschlossen worden war","weil die Studie beginnt","bevor man die Studie abschließt","falls die Studie endet"],"a":0,"why":"nach = zaman ilişkisi, nachdem."},{"q":"“zur Verbesserung der Qualität” →","o":["damit die Qualität verbessert wird","weil die Qualität schlecht ist","obwohl die Qualität steigt","nachdem die Qualität sank"],"a":0,"why":"zur + nominal amaç = damit/um … zu."},{"q":"“bei einer weiteren Verschärfung” →","o":["wenn sich die Lage weiter verschärft","obwohl die Lage besser wird","weil niemand reagiert","nachdem alles vorbei ist"],"a":0,"why":"bei + durum çoğu kez wenn/falls."},{"q":"“aufgrund fehlender Daten” →","o":["weil Daten fehlen","obwohl Daten fehlen","damit Daten fehlen","bevor Daten fehlen"],"a":0,"why":"aufgrund = neden."},{"q":"“während der Auswertung” →","o":["während die Daten ausgewertet werden","weil die Daten fehlen","nachdem alles fertig ist","damit man beginnt"],"a":0,"why":"Eş zamanlılık."},{"q":"Nominal yapı ne zaman özellikle uygundur?","o":["Bilgiyi yoğun ve resmî biçimde paketlemek gerektiğinde","Her konuşma cümlesinde","Sadece A1 düzeyinde","Sadece sorularda"],"a":0,"why":"Akademik/resmî registerda yoğunluk sağlar."}]},{"id":"cohesion","title":"Bağlaşıklık ve bağlaçlar","subtitle":"C1 düzeyinde metin ilişkileri","questions":[{"q":"Taviz: ___ die Stichprobe klein ist, sind die Ergebnisse relevant.","o":["Wenngleich","Folglich","Dadurch","Zumal"],"a":0,"why":"Wenngleich = her ne kadar."},{"q":"Sonuç: Die Nachfrage sank. ___ wurde das Angebot reduziert.","o":["Folglich","Wenngleich","Indem","Während"],"a":0,"why":"Folglich = bunun sonucunda."},{"q":"Karşılaştırmalı karşıtlık: Gruppe A profitiert. ___ entstehen Gruppe B Nachteile.","o":["Demgegenüber","Infolgedessen","Daher","Somit"],"a":0,"why":"Demgegenüber iki grubu karşı karşıya getirir."},{"q":"Koşul: Die Regel gilt, ___ keine Ausnahme genehmigt wird.","o":["sofern","obwohl","zumal","wodurch"],"a":0,"why":"sofern = şu koşulla ki/eğer."},{"q":"Ek gerekçe: Die Maßnahme ist teuer, ___ ihr Nutzen unklar ist.","o":["zumal","folglich","hingegen","indem"],"a":0,"why":"zumal ek/kuvvetlendirici gerekçe verir."},{"q":"Araç/yöntem: Man senkt Kosten, ___ man Prozesse automatisiert.","o":["indem","obwohl","sofern","während dagegen"],"a":0,"why":"indem = nasıl/yöntem."},{"q":"Gönderim: Es wurden zwei Modelle getestet. ___ erwies sich als robuster.","o":["Letzteres","Folglich","Wenngleich","Daher dass"],"a":0,"why":"Letzteres ikinci modele gider."},{"q":"“Nichtsdestotrotz” hangi ilişkiyi verir?","o":["Taviz/karşıtlık","Amaç","Zaman","Koşul"],"a":0,"why":"Beklenen sonuca rağmen karşıt durum."}]}],"styleSets":[{"id":"register","title":"Kayıt ve üslup","questions":[{"q":"Yarı resmî e-posta için en uygun ifade?","o":["Das ist echt Mist.","Ich möchte Sie auf eine Unstimmigkeit aufmerksam machen.","Ey, könnt ihr das fixen?","Mega nervig."],"a":1,"why":"Nazik, açık ve profesyonel kayıt."},{"q":"Akademik temkinli ifade?","o":["Das beweist hundertprozentig …","Die Befunde legen nahe, dass …","Jeder weiß, dass …","Ganz klar …"],"a":1,"why":"“legen nahe” kanıt derecesini uygun tutar."},{"q":"Tartışmada kibar itiraz?","o":["Unsinn.","Ich sehe den Punkt, allerdings …","Falsch!","Quatsch."],"a":1,"why":"Partneradäquat ve etkileşimli."},{"q":"Resmî öneri?","o":["Mach doch einfach …","Als mögliche Lösung schlage ich vor, …","Du musst halt …","Easy: …"],"a":1,"why":"Uygun register."},{"q":"Nötr görüş belirtme?","o":["Meines Erachtens …","Ich schwöre …","Voll krass …","Safe …"],"a":0,"why":"Nötr/resmî argümantasyon."},{"q":"Resmî talep?","o":["Wäre es möglich, …?","Gib mir …","Los, mach …","Kannste …?"],"a":0,"why":"Nazik ve uygun."},{"q":"Akademik sınırlama?","o":["Dies gilt allerdings nur unter der Voraussetzung, dass …","Das gilt immer.","Keine Ahnung, aber …","Ist halt so."],"a":0,"why":"Koşulu açıklar."},{"q":"Sunum geçişi?","o":["Jetzt mal egal.","Damit komme ich zum zweiten Aspekt.","Whatever.","Und so."],"a":1,"why":"Dinleyiciye yapı sinyali verir."}]},{"id":"paraphrase","title":"Parafraz","questions":[{"q":"“berücksichtigen” ≈","o":["in Betracht ziehen","verwerfen","bestreiten","verschweigen"],"a":0,"why":"İkisi de değerlendirmeye katmak."},{"q":"“auf etwas zurückzuführen sein” ≈","o":["durch etwas bedingt sein","etwas verhindern","etwas verbergen","etwas beschleunigen"],"a":0,"why":"Nedeni belirtir."},{"q":"“von großer Bedeutung” ≈","o":["maßgeblich","belanglos","zufällig","überflüssig"],"a":0,"why":"maßgeblich = önemli/belirleyici."},{"q":"“etwas außer Acht lassen” ≈","o":["etwas ignorieren","etwas fördern","etwas belegen","etwas erweitern"],"a":0,"why":"Göz ardı etmek."},{"q":"“einen Einwand erheben” ≈","o":["widersprechen","zustimmen","abschließen","zusammenfassen"],"a":0,"why":"İtiraz etmek."},{"q":"“sich als tragfähig erweisen” ≈","o":["funktionieren / belastbar sein","scheitern","verboten sein","unverständlich sein"],"a":0,"why":"Uygulanabilir/sağlam çıkmak."},{"q":"“die These untermauern” ≈","o":["die These stützen","die These vergessen","die These vermeiden","die These abschwächen"],"a":0,"why":"Kanıt/argümanla desteklemek."},{"q":"“eine Entwicklung zeichnet sich ab” ≈","o":["eine Entwicklung wird erkennbar","alles bleibt gleich","etwas wird verboten","etwas endet sofort"],"a":0,"why":"Bir eğilim görünür hale gelir."}]},{"id":"collocations","title":"C1 eşdizimler","questions":[{"q":"eine Schlussfolgerung ___","o":["ziehen","machen","bauen","stellen"],"a":0,"why":"eine Schlussfolgerung ziehen."},{"q":"eine Maßnahme ___","o":["ergreifen","schreiben","legen","laufen"],"a":0,"why":"Maßnahmen ergreifen."},{"q":"zur Debatte ___","o":["stehen","laufen","ziehen","fallen immer"],"a":0,"why":"zur Debatte stehen."},{"q":"einen Zusammenhang ___","o":["herstellen","kochen","setzen","laufen"],"a":0,"why":"einen Zusammenhang herstellen."},{"q":"eine Annahme ___","o":["in Frage stellen","ins Haus bringen","zu Fuß setzen","in Kraft machen"],"a":0,"why":"eine Annahme in Frage stellen."},{"q":"Verantwortung ___","o":["übernehmen","nehmen auf","machen","bauen"],"a":0,"why":"Verantwortung übernehmen."},{"q":"einen Antrag ___","o":["stellen","setzen","machen immer","ziehen"],"a":0,"why":"einen Antrag stellen."},{"q":"unter Druck ___","o":["geraten","kommen zu","ziehen","leisten"],"a":0,"why":"unter Druck geraten/stehen."}]},{"id":"nuance","title":"Nüans ve kanıt derecesi","questions":[{"q":"“legt nahe” hangi güçte?","o":["işaret ediyor / olası sonuç","kesin kanıtlıyor","reddediyor","yasaklıyor"],"a":0,"why":"Temkinli sonuç."},{"q":"“dürfte” (öznel) çoğu zaman?","o":["muhtemelen","kesinlikle","yasaktır","geçmiş emir"],"a":0,"why":"Yüksek olasılık/varsayım."},{"q":"“keineswegs” ne yapar?","o":["güçlü olumsuzlama","örnek verir","sonuç çıkarır","zaman gösterir"],"a":0,"why":"Kesinlikle değil."},{"q":"“durchaus” hangi nüansı taşıyabilir?","o":["beklenenden daha olumlu/onaylayıcı vurgu","tam ret","zaman","sayısal kesinlik"],"a":0,"why":"“gayet / durchaus” olumlu vurgu yapabilir."},{"q":"“nur bedingt” ne demektir?","o":["yalnızca sınırlı ölçüde","tamamen","kesinlikle","hiçbir koşulda"],"a":0,"why":"Koşullu/sınırlı geçerlilik."},{"q":"“weitgehend” ≈","o":["büyük ölçüde","hiç","tam olarak her zaman","rastgele"],"a":0,"why":"Tam değil ama büyük ölçüde."},{"q":"“kaum” ne ifade eder?","o":["çok az / neredeyse hiç","çok fazla","kesin","gereklilik"],"a":0,"why":"Düşük derece."},{"q":"“angeblich” ne sinyali verir?","o":["iddia edilen, doğrulanmamış bilgi","kesin kanıt","emir","izin"],"a":0,"why":"Kaynağa mesafe."}]}],"readingPractice":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Viele Städte testen sogenannte Superblocks. Dabei werden mehrere Straßen zu größeren Wohnbereichen zusammengefasst, in denen der Durchgangsverkehr stark begrenzt wird. Die Idee zielt ___(1)___, öffentlichen Raum neu zu verteilen. Flächen, die zuvor fast ausschließlich Autos ___(2)___, können für Bäume, Sitzplätze oder Spielbereiche genutzt werden. Kritiker weisen jedoch ___(3)___, dass Verkehr nicht einfach verschwindet, sondern sich verlagern kann. Deshalb kommt es ___(4)___ eine sorgfältige Planung an. Erste Auswertungen zeigen, dass die Akzeptanz steigt, wenn Anwohner frühzeitig ___(5)___ die Gestaltung einbezogen werden. Entscheidend ist außerdem, die Auswirkungen nicht nur kurzfristig, ___(6)___ über mehrere Jahre zu beobachten. So lässt sich prüfen, ob die Maßnahmen tatsächlich ___(7)___ einer besseren Luftqualität beitragen und ob benachbarte Straßen unverhältnismäßig ___(8)___ werden.","items":[{"o":["darauf ab","davon aus","dazu bei","damit ein"],"a":0},{"o":["zur Verfügung standen","in Anspruch nahmen","zugrunde lagen","in Kraft traten"],"a":1},{"o":["darauf hin","darüber aus","dazu bei","davon ab"],"a":0},{"o":["auf","an","um","für"],"a":1},{"o":["an","in","bei","zu"],"a":1},{"o":["aber auch","sondern","obwohl","währenddessen"],"a":1},{"o":["zu","bei","mit","an"],"a":0},{"o":["belastet","überzeugt","verfasst","erfasst"],"a":0}]},"part2":{"title":"Bölüm 2 · Yoğun bilgi içeren makale","text":"Immer mehr Unternehmen erproben eine Vier-Tage-Woche, doch hinter dem Begriff verbergen sich unterschiedliche Modelle. Manche reduzieren die Wochenarbeitszeit bei gleichem Lohn, andere verteilen die bisherige Arbeitszeit lediglich auf vier längere Tage. Für die Bewertung ist diese Unterscheidung entscheidend. Studien zu Pilotprojekten berichten häufig von höherer Zufriedenheit und weniger Fehltagen. Gleichzeitig warnen Forschende davor, aus kleinen, freiwillig teilnehmenden Stichproben allgemeine Schlüsse zu ziehen. Unternehmen, die sich für Pilotprojekte melden, sind oft bereits offen für flexible Arbeitsformen und verfügen über günstige organisatorische Voraussetzungen.\n\nEin zentrales Ergebnis vieler Versuche ist, dass die Produktivität nicht automatisch sinkt, wenn Arbeitszeit reduziert wird. Teams streichen etwa wenig wirksame Besprechungen, bündeln Kommunikationszeiten und automatisieren Routinen. Diese Verdichtung kann jedoch problematisch werden, wenn die gleiche Arbeitsmenge lediglich in weniger Zeit erledigt werden soll. Beschäftigte berichten dann zwar von einem zusätzlichen freien Tag, aber auch von stärkerem Zeitdruck an den übrigen Tagen. Besonders in Bereichen mit Schichtbetrieb oder direktem Kundenkontakt ist die Umsetzung kompliziert, weil Öffnungszeiten und Besetzung weiterhin gewährleistet werden müssen.\n\nAuch die langfristige Wirkung ist noch nicht abschließend geklärt. Während die Motivation zu Beginn eines Pilotprojekts häufig deutlich steigt, kann ein Teil dieses Effekts auf den Neuigkeitswert zurückzuführen sein. Daher fordern Arbeitsforscher längere Beobachtungszeiträume. Sie betonen zudem, dass die Vier-Tage-Woche kein einzelnes Instrument ist, das unabhängig von Führung, Personaldecke und Arbeitsorganisation funktioniert. Ein erfolgreiches Modell müsse an Branche und Tätigkeit angepasst werden.\n\nFür Beschäftigte ist nicht nur die Zahl der Arbeitstage relevant. Planbarkeit, Autonomie und die Möglichkeit, konzentriert zu arbeiten, spielen ebenfalls eine große Rolle. Einige Untersuchungen zeigen sogar, dass Beschäftigte eine geringere Wochenarbeitszeit mit etwas weniger Einkommen akzeptieren würden, wenn sie dafür verlässlich über ihre Zeit verfügen könnten. Das spricht dafür, Arbeitszeitpolitik nicht auf eine einzige Kennzahl zu reduzieren.\n\nIn der öffentlichen Debatte wird die Vier-Tage-Woche häufig entweder als Zukunftsmodell oder als unrealistische Wohlfühlidee dargestellt. Die Forschung zeichnet ein differenzierteres Bild: Unter passenden Bedingungen kann sie Vorteile bringen, doch sie löst weder Personalmangel noch schlechte Prozesse von selbst. Entscheidend ist somit weniger die Zahl Vier als die Frage, wie Arbeit organisiert wird.","items":[{"q":"Warum ist der Begriff Vier-Tage-Woche laut Text nicht eindeutig?","o":["Weil nur öffentliche Betriebe ihn nutzen.","Weil unterschiedliche Modelle dahinterstehen.","Weil die Wochenarbeitszeit immer gleich bleibt."],"a":1},{"q":"Warum mahnen Forschende bei Pilotstudien zur Vorsicht?","o":["Teilnehmende Unternehmen können nicht repräsentativ sein.","Die Produktivität wird nie gemessen.","Die Projekte dauern immer zu lange."],"a":0},{"q":"Wie kann Produktivität trotz weniger Arbeitszeit stabil bleiben?","o":["Durch längere Pausen.","Durch effizientere Abläufe und weniger unwirksame Tätigkeiten.","Durch zusätzliche unbezahlte Arbeit."],"a":1},{"q":"Welches Risiko nennt der Text bei Arbeitsverdichtung?","o":["Mehr Zeitdruck an den Arbeitstagen.","Zu viele freie Mitarbeiter.","Sinkende Öffnungszeiten in allen Branchen."],"a":0},{"q":"Warum sind längere Studien nötig?","o":["Um einen möglichen Neuigkeitseffekt von dauerhaften Wirkungen zu trennen.","Weil bisher keine Daten existieren.","Weil nur Gehälter untersucht wurden."],"a":0},{"q":"Was ist Beschäftigten laut Text ebenfalls wichtig?","o":["Nur die Zahl der Urlaubstage.","Planbarkeit und Autonomie.","Einheitliche Arbeitszeiten für alle Branchen."],"a":1},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Vier Tage sind grundsätzlich optimal.","Die konkrete Arbeitsorganisation ist wichtiger als die reine Zahl der Tage.","Das Modell ist nur im Schichtbetrieb sinnvoll."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Digitale Lernplattformen versprechen, Unterricht stärker zu individualisieren. "," Lehrkräfte erhalten dadurch detaillierte Informationen über Lernfortschritte. "," Gerade hier beginnt jedoch die Debatte über Datenschutz. "," Solche Daten können pädagogisch hilfreich sein, zugleich lassen sich daraus umfassende Profile ableiten. "," Hinzu kommt, dass algorithmische Empfehlungen nicht neutral sind. "," Werden bestimmte Aufgabentypen häufiger vorgeschlagen, kann dies langfristig beeinflussen, welche Kompetenzen Lernende entwickeln. "," Deshalb fordern Fachleute transparente Kriterien und die Möglichkeit, automatisierte Empfehlungen zu übersteuern. "," Entscheidend ist am Ende, dass Technik pädagogische Entscheidungen unterstützt, nicht ersetzt. "," Nur dann kann Personalisierung einen echten Mehrwert bieten."],"candidates":["A: Systeme können Aufgaben automatisch an das bisherige Leistungsniveau anpassen.","B: Dafür müssen allerdings große Mengen an Nutzungsdaten verarbeitet werden.","C: Aus diesem Grund sollten Schulen sämtliche digitalen Angebote vermeiden.","D: Denn Modelle spiegeln immer auch die Daten und Annahmen wider, auf denen sie beruhen.","E: Eine technische Empfehlung kann also unbemerkt zu einer pädagogischen Vorgabe werden.","F: Gleichzeitig bleibt die professionelle Beurteilung durch Lehrkräfte unverzichtbar.","G: Viele Schulen ersetzen deshalb alle Lehrbücher durch Tablets.","H: Besonders wichtig ist, dass Betroffene nachvollziehen können, wie eine Empfehlung entsteht.","I: Diese Forderung betrifft sowohl Anbieter als auch Bildungseinrichtungen.","J: Personalisierung wird damit zu einer Frage der Kontrolle und Verantwortlichkeit."],"answers":[0,1,9,3,4,7,8,5]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Prof. Berger","text":"Generative KI kann Studierenden beim Strukturieren helfen. Problematisch wird es, wenn der Denkprozess ausgelagert wird. Ich würde die Werkzeuge daher nicht verbieten, sondern Aufgaben so gestalten, dass Zwischenschritte und Quellen transparent gemacht werden müssen."},{"name":"B · Dr. Kaya","text":"Für mich steht Chancengleichheit im Vordergrund. Wenn leistungsfähige Systeme kostenpflichtig sind, dürfen Prüfungen nicht voraussetzen, dass alle Studierenden Zugang haben. Institutionen müssten entweder gleichwertige Zugänge bereitstellen oder die Nutzung begrenzen."},{"name":"C · Lena Hoffmann","text":"Ich nutze KI vor allem, um Gegenargumente zu finden. Das zwingt mich, meine Position zu schärfen. Texte lasse ich aber nicht vollständig erzeugen, weil ich sonst kaum merke, ob ich den Stoff wirklich verstanden habe."},{"name":"D · Markus Voss","text":"Die Debatte konzentriert sich zu stark auf Betrug. Interessanter ist, welche Kompetenzen künftig relevant sind. Wer KI-Ergebnisse prüfen, korrigieren und sinnvoll einordnen kann, besitzt eine neue Form von Fachkompetenz. Hochschulen sollten das systematisch lehren."}],"items":[{"q":"Wer sieht Transparenz über den Arbeitsprozess als zentral an?","a":0},{"q":"Wer betont ungleichen Zugang zu Technik?","a":1},{"q":"Wer nutzt KI gezielt zur Prüfung der eigenen Argumente?","a":2},{"q":"Wer fordert, KI-Kompetenz ausdrücklich zu unterrichten?","a":3},{"q":"Wer lehnt ein generelles Verbot ab?","a":0},{"q":"Wer verbindet die Frage mit Fairness in Prüfungen?","a":1},{"q":"Wer nennt eigenes Verständnis als Grenze der Nutzung?","a":2}]}},"listeningPractice":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writingForum":[{"id":"wf1","title":"Üniversitede zorunlu staj","prompt":"Bir eğitim forumunda üniversite programlarında zorunlu stajın gerekli olup olmadığını tartışın.","points":["Zorunlu stajın bir avantajını açıklayın.","Olası bir dezavantajı gerekçelendirin.","Kendi ülkenizden veya deneyiminizden bir örnek verin.","Hangi koşullarda zorunlu olmasını uygun gördüğünüzü değerlendirin."],"target":230,"model":"Zorunlu staj, teorik bilginin iş yaşamıyla bağını güçlendirebilir. Özellikle öğrenciler mesleğin günlük gerçeklerini henüz tanımıyorsa, kısa süreli de olsa uygulama deneyimi kararlarını daha bilinçli hâle getirir. Bununla birlikte, her stajın otomatik olarak nitelikli bir öğrenme ortamı sunduğunu varsaymak doğru değildir. Öğrencilerin yalnızca rutin işler yaptığı ve ücret almadığı durumlarda zorunluluk haksız bir yük yaratabilir.\n\nBu nedenle bana göre belirleyici olan “staj olsun mu olmasın mı?” sorusu değil, stajın hangi standartlara göre düzenlendiğidir. Örneğin üniversite, öğrenme hedeflerini önceden belirleyebilir ve kurumdan düzenli geribildirim isteyebilir. Ayrıca ekonomik durumu sınırlı öğrencilerin ücretsiz çalışmak zorunda kalmaması için asgari bir ödeme veya burs sistemi düşünülmelidir.\n\nTürkiye’de ve Almanya’da bazı programlarda uygulama dönemi zaten önemli bir rol oynuyor. Başarılı örneklerde öğrenci, stajın ardından yaptığı işi analiz eden bir rapor hazırlıyor. Bu, deneyimi yalnızca “işte bulunmak” olmaktan çıkarıp öğrenme sürecine dönüştürüyor.\n\nSonuç olarak zorunlu stajı genel olarak destekliyorum; ancak yalnızca kalite ölçütleri, akademik rehberlik ve makul maddi koşullar garanti edildiğinde."},{"id":"wf2","title":"Dört günlük çalışma haftası","prompt":"Bir çevrimiçi forumda dört günlük çalışma haftasının yaygınlaştırılıp yaygınlaştırılmaması hakkında yazın.","points":["Modelin olası faydalarını açıklayın.","Bir uygulama sorununu tartışın.","Bir örnekle görüşünüzü destekleyin.","Sonuçta hangi yaklaşımı önerdiğinizi belirtin."],"target":230,"model":""},{"id":"wf3","title":"Yapay zekâ ile eğitim","prompt":"Üniversitelerde üretken yapay zekâ kullanımının nasıl düzenlenmesi gerektiğini tartışın.","points":["Bir fırsatı açıklayın.","Bir riski gerekçelendirin.","Somut bir kullanım örneği verin.","Kendi düzenleme önerinizi sunun."],"target":230,"model":""},{"id":"wf4","title":"Şehir merkezinde otomobil","prompt":"Şehir merkezlerinde özel otomobil kullanımının ciddi biçimde sınırlandırılması hakkında görüş yazın.","points":["Bir çevresel veya sosyal faydayı açıklayın.","Bir karşı argümanı ele alın.","Başka bir şehir/ülkeden örnek verin.","Dengeli bir çözüm önerin."],"target":230,"model":""},{"id":"wf5","title":"Ücretsiz yükseköğretim","prompt":"Yükseköğretimin herkes için tamamen ücretsiz olması gerekip gerekmediğini tartışın.","points":["Bir eşitlik argümanı sunun.","Finansman açısından bir sorun ele alın.","Bir sistem örneği verin.","Kendi sonucunuzu gerekçelendirin."],"target":230,"model":""},{"id":"wf6","title":"Uzaktan çalışma hakkı","prompt":"Uygun mesleklerde çalışanların haftanın belirli günlerinde uzaktan çalışma hakkına sahip olup olmaması üzerine yazın.","points":["Çalışan açısından bir faydayı açıklayın.","İşveren açısından bir riski tartışın.","Bir örnek verin.","Hangi koşullarda hakkı desteklediğinizi açıklayın."],"target":230,"model":""}],"writingEmail":[{"id":"we1","title":"Kütüphane çalışma alanı","prompt":"Üniversite kütüphanesinde rezervasyon yaptığınız sessiz çalışma odası sürekli grup toplantıları için kullanılıyor. Kütüphane yönetimine yazın.","points":["Sorunu açıklayın.","Bunun çalışmanızı nasıl etkilediğini belirtin.","Somut bir çözüm önerin.","Nazikçe hızlı yanıt/anlayış isteyin."],"target":120,"model":"Sehr geehrte Damen und Herren,\n\nich möchte Sie auf ein Problem mit den als „still“ ausgewiesenen Arbeitsräumen aufmerksam machen. Obwohl ich mehrfach einen Einzelarbeitsplatz reserviert habe, wurden die Räume gleichzeitig für lautere Gruppentreffen genutzt. Dadurch ist konzentriertes Arbeiten, insbesondere während meiner Prüfungsvorbereitung, kaum möglich.\n\nIch schlage vor, die Nutzungsregeln bei der Reservierung deutlicher anzuzeigen und für Gruppen separate Räume vorzusehen. Zusätzlich könnte das Bibliothekspersonal bei wiederholten Verstößen gezielt darauf hinweisen.\n\nIch wäre Ihnen dankbar, wenn Sie prüfen könnten, wie die vereinbarte ruhige Nutzung künftig besser gewährleistet werden kann. Vielen Dank für Ihr Verständnis.\n\nMit freundlichen Grüßen\nAylin Demir"},{"id":"we2","title":"Seminer tarihi değişikliği","prompt":"Bir seminer tarihi kısa süre önce değiştirildi ve yeni tarih zorunlu bir iş vardiyanızla çakışıyor. Öğretim görevlisine yazın.","points":["Durumu açıklayın.","Neden katılamadığınızı belirtin.","Bir alternatif önerin.","Anlayış rica edin."],"target":120,"model":""},{"id":"we3","title":"Yanlış fatura","prompt":"Bir dil kursu size anlaşılmış ücretten daha yüksek bir fatura gönderdi. Kurs yönetimine yazın.","points":["Farkı açıklayın.","Anlaşmayı referans gösterin.","Düzeltme önerin/isteyin.","Nazik kapanış yapın."],"target":120,"model":""},{"id":"we4","title":"Ofiste gürültü","prompt":"Yeni açık ofiste sürekli telefon görüşmeleri işinizi ciddi biçimde etkiliyor. Yöneticinize yazın.","points":["Sorunu somutlaştırın.","İş üzerindeki etkisini açıklayın.","Uygulanabilir çözüm önerin.","İşbirliğine açık olduğunuzu gösterin."],"target":120,"model":""},{"id":"we5","title":"Kurs materyali erişimi","prompt":"Çevrimiçi kurs materyallerine iki gündür erişemiyorsunuz ve son teslim tarihi yaklaşıyor. Teknik desteğe yazın.","points":["Sorunu tarif edin.","Denediğiniz adımları belirtin.","Acil çözüm/uzatma önerin.","Yanıt rica edin."],"target":120,"model":""},{"id":"we6","title":"Toplantı gündemi","prompt":"Toplantı gündeminde sizin alanınızla ilgili kritik bir konu eksik. Organizatöre yazın.","points":["Eksik konuyu belirtin.","Neden önemli olduğunu açıklayın.","Gündeme eklenmesini önerin.","Nazikçe teyit isteyin."],"target":120,"model":""}],"speakingPresentations":[{"id":"sp1","title":"Üniversitelerde yapay zekâ","intro":"Bir seminerde üretken yapay zekânın üniversite eğitimindeki rolü üzerine kısa bir sunum yapın.","points":["Somut bir kullanım örneği verin.","Bir fırsatı ve bir riski karşılaştırın.","Hangi kuralların gerekli olduğunu açıklayın.","Kendi değerlendirmenizle sonuçlandırın."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze ziehen?"]},{"id":"sp2","title":"Şehirde yeşil alan","intro":"Büyük şehirlerde yeşil alanların genişletilmesi hakkında sunum yapın.","points":["Bir güncel sorunu örnekleyin.","Çevresel ve sosyal etkileri açıklayın.","Olası maliyet/çatışmaları tartışın.","Bir öncelik önerin."],"questions":["Wer sollte solche Projekte finanzieren?","Wie kann man Nutzungskonflikte lösen?"]},{"id":"sp3","title":"Dört günlük çalışma haftası","intro":"Dört günlük çalışma haftasının fırsat ve sınırlarını sunun.","points":["Bir model tanımlayın.","Fayda ve riski tartışın.","Bir sektör örneği verin.","Kendi koşullu görüşünüzü belirtin."],"questions":["Für welche Branchen wäre das Modell besonders schwierig?","Wie könnte man Produktivität sinnvoll messen?"]},{"id":"sp4","title":"Üniversitede devam zorunluluğu","intro":"Üniversite derslerinde devam zorunluluğunu değerlendirin.","points":["Bir gerekçe sunun.","Karşı görüşü ele alın.","Kendi deneyiminizden örnek verin.","Alternatif bir model önerin."],"questions":["Sollte Anwesenheit benotet werden?","Wie könnte man aktive Teilnahme anders messen?"]},{"id":"sp5","title":"Toplu taşıma ücretsiz mi?","intro":"Şehir içi toplu taşımanın ücretsiz olması gerekip gerekmediğini tartışan bir sunum yapın.","points":["Bir avantaj açıklayın.","Finansman sorununu ele alın.","Bir şehir örneği verin.","Kendi çözümünüzü önerin."],"questions":["Wer sollte die Kosten tragen?","Würde kostenloser ÖPNV automatisch den Autoverkehr senken?"]},{"id":"sp6","title":"Uzaktan çalışma","intro":"Uzaktan çalışmanın uzun vadeli etkileri üzerine sunum yapın.","points":["Çalışan açısından bir etki açıklayın.","Şirket açısından bir etki açıklayın.","Takım iletişimini değerlendirin.","Hibrit bir model önerin."],"questions":["Wie viel Präsenz halten Sie für sinnvoll?","Welche Aufgaben eignen sich nicht fürs Homeoffice?"]}],"speakingDiscussions":[{"id":"sd1","title":"KI ile yazılmış ödevler","input":"Bir üniversite, üretken yapay zekâ ile hazırlanmış ödevlerin tamamen yasaklanmasını tartışıyor.","points":["Yasak ne kadar uygulanabilir?","Öğrenme hedefleri nasıl korunur?","Şeffaflık kuralları yeterli olabilir mi?","Ortak bir öneri geliştirin."]},{"id":"sd2","title":"Şehir merkezinde araç kısıtlaması","input":"Belediye, merkezde özel araç trafiğini yarıya indirmeyi planlıyor.","points":["Çevresel etkiler","Esnaf ve erişilebilirlik","Alternatif ulaşım","Ortak öncelikler"]},{"id":"sd3","title":"Zorunlu gönüllü hizmet","input":"Genç yetişkinler için altı aylık toplumsal hizmet zorunluluğu öneriliyor.","points":["Toplumsal fayda","Bireysel özgürlük","Eğitim/işe etkisi","Olası alternatif model"]},{"id":"sd4","title":"Dört günlük çalışma haftası","input":"Bir şirket ücret azaltmadan dört günlük haftayı kalıcılaştırmak istiyor.","points":["Verimlilik","Müşteri erişimi","Çalışan yükü","Pilot uygulama ölçütleri"]},{"id":"sd5","title":"Üniversite harcı","input":"Devlet üniversitelerinde düşük miktarlı genel öğrenim harcı öneriliyor.","points":["Finansman","Eşitlik","Muafiyet/burs","Ortak çözüm"]},{"id":"sd6","title":"Sosyal medyada yaş sınırı","input":"16 yaş altı için sosyal medya hesaplarına daha sıkı yaş doğrulaması öneriliyor.","points":["Çocuk koruma","Mahremiyet","Uygulanabilirlik","Ebeveyn/eğitim rolü"]}],"goetheMock":{"reading":{"part1":{"title":"Bölüm 1 · Sözcük boşlukları","text":"Solaranlagen und begrünte Dächer wurden lange als konkurrierende Nutzungen betrachtet. Neuere Planungsansätze versuchen jedoch, beide Systeme auf derselben Fläche ___(1)___. Pflanzen können durch Verdunstung und Schatten dazu beitragen, dass sich Solarmodule an heißen Tagen weniger stark erwärmen und dadurch effizienter ___(2)___. Allerdings eignet sich nicht jedes Gebäude für eine solche Kombination. Tragfähigkeit, Windlast und Zugang für die Wartung müssen bereits in der Planung ___(3)___ werden. Fachleute weisen außerdem darauf hin, dass die Auswahl der Pflanzen an die besonderen Bedingungen auf dem Dach ___(4)___ sein muss. Arten, die viel Wasser benötigen, sind in trockenen Sommern problematisch. Gut geplante Systeme können dagegen Regenwasser zurückhalten und die Artenvielfalt fördern. Ob sich die höheren Anfangskosten langfristig ___(5)___, hängt von Standort, Bauweise und Pflege ab. Entscheidend ist deshalb, die Wirkung nicht anhand einzelner Beispiele zu beurteilen, ___(6)___ über mehrere Jahre systematisch zu erfassen. Erst dann lässt sich verlässlich sagen, unter welchen Bedingungen sich beide Nutzungen gegenseitig ___(7)___ und wo Zielkonflikte entstehen. Kommunen, die solche Projekte fördern möchten, sollten daher nicht nur technische Standards festlegen, ___(8)___ auch Beratung und langfristige Evaluation einplanen.","items":[{"o":["zu verbinden","verbunden","verbindlich","Verbindung"],"a":0},{"o":["arbeiten","wirken","leisten","erzeugen"],"a":1},{"o":["berücksichtigt","beobachtet","begründet","verhindert"],"a":0},{"o":["angepasst","angewiesen","aufgeteilt","ausgelöst"],"a":0},{"o":["auszahlen","auszahlt","bezahlen","bezahlt"],"a":1},{"o":["sondern","obwohl","damit","während"],"a":0},{"o":["ergänzen","ersetzen","vermeiden","begrenzen"],"a":0},{"o":["aber","sondern","dennoch","obwohl"],"a":1}]},"part2":{"title":"Bölüm 2 · Ana fikirler ve ayrıntılı bilgiler","text":"Viele Hochschulen versuchen seit einigen Jahren, Prinzipien der offenen Wissenschaft stärker zu verankern. Häufig wird darunter vor allem verstanden, wissenschaftliche Artikel kostenlos zugänglich zu machen. Open Science umfasst jedoch deutlich mehr: Auch Forschungsdaten, Methoden und teilweise sogar Auswertungsschritte sollen so dokumentiert werden, dass andere Forschende Ergebnisse nachvollziehen und - soweit möglich - überprüfen können.\n\nBefürworter sehen darin einen wichtigen Beitrag zur Qualitätssicherung. Wenn Datensätze und Analysewege zugänglich sind, lassen sich Fehler leichter entdecken und Ergebnisse eher reproduzieren. Zudem können bereits erhobene Daten für neue Fragestellungen genutzt werden. Das spart unter Umständen Zeit und Ressourcen. Allerdings ist nicht jeder Datensatz ohne Weiteres veröffentlichbar. Besonders in Medizin, Psychologie und Sozialforschung können Angaben enthalten sein, die Rückschlüsse auf einzelne Personen zulassen. Datenschutz und informierte Einwilligung müssen deshalb von Beginn an berücksichtigt werden.\n\nEin weiteres Problem ist der Arbeitsaufwand. Daten so aufzubereiten, dass Außenstehende sie tatsächlich verstehen, erfordert klare Dokumentation, standardisierte Formate und häufig zusätzliche Metadaten. Forschende kritisieren, dass diese Arbeit in vielen Karrieresystemen bislang kaum anerkannt wird. Wer Zeit in saubere Dokumentation investiert, hat nicht automatisch bessere Chancen bei Bewerbungen oder Förderanträgen. Fachleute fordern daher, offene Forschungspraktiken auch bei Leistungsbewertungen stärker zu berücksichtigen.\n\nKontrovers diskutiert wird außerdem, ob Offenheit in jedem Stadium sinnvoll ist. Bei laufenden Projekten kann eine zu frühe Veröffentlichung Ideen gefährden, an denen Teams über Jahre gearbeitet haben. Andere halten dagegen, dass transparente Vorregistrierungen gerade verhindern können, dass nur erwünschte Resultate veröffentlicht werden. Ein einheitliches Modell für alle Disziplinen dürfte daher kaum funktionieren.\n\nDie Debatte zeigt, dass offene Wissenschaft weder eine einfache technische Lösung noch ein Selbstzweck ist. Sie kann Vertrauen und Nachprüfbarkeit fördern, wenn rechtliche, ethische und organisatorische Voraussetzungen stimmen. Entscheidend ist weniger, möglichst alles öffentlich zu machen, als nachvollziehbar zu begründen, was geteilt werden kann, was geschützt werden muss und wie wissenschaftliche Arbeit dafür angemessen honoriert wird.","items":[{"q":"Was umfasst Open Science laut Text über frei zugängliche Artikel hinaus?","o":["Nur öffentliche Vorträge","Auch Daten, Methoden und Auswertungsschritte","Ausschließlich kostenlose Lehrbücher"],"a":1},{"q":"Welchen Vorteil nennen Befürworter?","o":["Fehler und Ergebnisse lassen sich leichter überprüfen.","Forschung wird grundsätzlich billiger.","Datenschutz wird überflüssig."],"a":0},{"q":"Warum können Forschungsdaten nicht immer vollständig veröffentlicht werden?","o":["Weil Dateien meist zu groß sind.","Weil Rückschlüsse auf Personen möglich sein können.","Weil Zeitschriften dies grundsätzlich verbieten."],"a":1},{"q":"Welche Schwierigkeit betrifft die Aufbereitung von Daten?","o":["Sie erfordert zusätzliche Dokumentation und Zeit.","Sie ist nur mit kommerzieller Software möglich.","Sie verhindert weitere Forschung mit den Daten."],"a":0},{"q":"Was wird an heutigen Karrieresystemen kritisiert?","o":["Offene Forschungspraktiken werden oft zu wenig anerkannt.","Veröffentlichungen spielen überhaupt keine Rolle.","Forschende dürfen keine Metadaten erstellen."],"a":0},{"q":"Warum ist eine zu frühe Offenlegung umstritten?","o":["Sie kann langjährig entwickelte Ideen gefährden.","Sie macht Vorregistrierungen unmöglich.","Sie ist in allen Fächern gesetzlich verboten."],"a":0},{"q":"Welche Schlussfolgerung zieht der Text?","o":["Alle Forschungsdaten sollten ohne Ausnahme öffentlich sein.","Offenheit muss fachlich, rechtlich und ethisch differenziert gestaltet werden.","Open Science ist vor allem eine technische Speicherfrage."],"a":1}]},"part3":{"title":"Bölüm 3 · Cümleleri yeniden yerleştirme","segments":["Da sommerliche Hitze in Städten zunimmt, gewinnt die kühlende Wirkung von Bäumen an Bedeutung. ___(1)___","Pauschale Angaben wie „ein Baum senkt die Temperatur um mehrere Grad“ sind deshalb nur begrenzt aussagekräftig. ___(2)___","Hinzu kommt, dass Stadtbäume selbst stärker unter Trockenheit und Hitze leiden. ___(3)___","Planerinnen und Planer setzen daher zunehmend auf eine größere Artenvielfalt. ___(4)___","Vielfalt allein reicht jedoch nicht aus. Auch der Wasserbedarf muss berücksichtigt werden. ___(5)___","Ein weiterer Faktor ist das Alter der Bäume. Große, etablierte Kronen können deutlich mehr Schatten spenden als junge Pflanzungen. ___(6)___","Bei neuen Programmen stellt sich außerdem die Frage, in welchen Stadtteilen zuerst investiert werden soll. ___(7)___","Damit wird Stadtbegrünung nicht nur zu einer ästhetischen, sondern auch zu einer langfristigen Gesundheits- und Gerechtigkeitsfrage. ___(8)___"],"candidates":["A: Denn die Wirkung hängt unter anderem von Art, Alter, Kronengröße und Wasserversorgung ab.","B: Dieses Thema spielt ausschließlich in ländlichen Regionen eine Rolle.","C: Klimamodelle deuten darauf hin, dass manche traditionell verwendeten Arten künftig stärker unter Stress geraten.","D: Monokulturen können bei einer einzigen Krankheit besonders große Verluste erleiden.","E: Dadurch sinken die Pflegekosten in jedem Fall auf null.","F: Das Fällen ausgewachsener Bäume lässt sich daher kurzfristig kaum durch Neupflanzungen ausgleichen.","G: Priorität sollten besonders heiße und bislang schlecht mit Grünflächen versorgte Quartiere erhalten.","H: Vor allem in trockenen Regionen muss geklärt werden, woher zusätzliches Bewässerungswasser kommen kann.","I: Ziel sollte es sein, in jeder Straße dieselbe Baumart zu pflanzen.","J: Der Blick verschiebt sich damit von heutigen Standortbedingungen auf die Widerstandsfähigkeit der nächsten Jahrzehnte."],"answers":[0,9,2,3,7,5,6,4]},"part4":{"title":"Bölüm 4 · Görüşleri eşleştirme","texts":[{"name":"A · Dr. Richter","text":"Aufzeichnungen von Lehrveranstaltungen können das Nacharbeiten erleichtern. Eine permanente Aufnahme kann aber offene Diskussionen hemmen, besonders bei sensiblen Themen. Deshalb sollte je nach Veranstaltungsform entschieden werden."},{"name":"B · Prof. Lang","text":"Ich halte Aufzeichnungen grundsätzlich für sinnvoll. Studierende mit Krankheit, Betreuungspflichten oder Sprachbarrieren profitieren besonders. Entscheidend ist, dass Lehrende wissen, wann aufgezeichnet wird und welche Beiträge später veröffentlicht werden."},{"name":"C · Dr. Seidel","text":"Die Debatte konzentriert sich zu stark auf Technik. Eine Aufnahme ersetzt keine gute Lehrgestaltung. Wenn Studierende wissen, dass alles später verfügbar ist, kann sogar die aktive Teilnahme sinken. Aufzeichnungen sollten daher nur ergänzend eingesetzt werden."},{"name":"D · Prof. Kramer","text":"Bei großen Vorlesungen überwiegen für mich die Vorteile. In kleinen Seminaren mit persönlicher Diskussion würde ich dagegen meist darauf verzichten. Eine einheitliche Regel für alle Lehrveranstaltungen wäre pädagogisch wenig sinnvoll."}],"items":[{"q":"Wer warnt ausdrücklich davor, dass Aufzeichnungen offene Diskussionen beeinträchtigen können?","a":0},{"q":"Wer betont besonders den Nutzen für Studierende mit erschwertem Zugang zur Veranstaltung?","a":1},{"q":"Wer befürchtet, dass die aktive Teilnahme durch die spätere Verfügbarkeit sinken kann?","a":2},{"q":"Wer unterscheidet klar zwischen großen Vorlesungen und kleinen Seminaren?","a":3},{"q":"Wer hält transparente Regeln darüber, was aufgezeichnet und veröffentlicht wird, für entscheidend?","a":1},{"q":"Wer argumentiert, dass Technik gute Didaktik nicht ersetzen kann?","a":2},{"q":"Wer lehnt eine einheitliche Regel für alle Veranstaltungsformen ab?","a":3}]}},"listening":{"part1":{"title":"Bölüm 1 · Podcast eşleştirme","plays":1,"script":"Willkommen zu „Ideen im Alltag“. Heute stelle ich drei neue Sachbücher vor. Das erste Buch, „Leise Städte“, untersucht, wie Lärm unsere Gesundheit beeinflusst. Besonders stark ist der historische Vergleich: Die Autorin zeigt, wie sich Geräuschquellen seit der Industrialisierung verändert haben und warum absolute Stille in einer Stadt weder realistisch noch unbedingt wünschenswert ist. Das zweite Buch, „Reparieren statt ersetzen“, beschäftigt sich mit Produktdesign. Der Autor besucht Werkstätten, Start-ups und kommunale Reparaturzentren. Er argumentiert, dass langlebige Produkte nicht nur eine technische, sondern auch eine politische Frage sind. Das dritte Buch heißt „Die Kunst des Wartens“. Eine Psychologin verbindet Forschung zu Aufmerksamkeit mit persönlichen Beobachtungen. Sie erklärt, warum Wartezeiten heute als besonders belastend erlebt werden und wie kleine Unterbrechungen sogar kreative Prozesse fördern können.","labels":["A · Leise Städte","B · Reparieren statt ersetzen","C · Die Kunst des Wartens"],"items":[{"q":"Historische Entwicklungen spielen eine wichtige Rolle.","a":0},{"q":"Politische Rahmenbedingungen werden thematisiert.","a":1},{"q":"Persönliche Erfahrungen werden mit Forschung verbunden.","a":2},{"q":"Es geht um die Lebensdauer von Gegenständen.","a":1},{"q":"Ein vermeintlich negativer Zustand kann Vorteile haben.","a":2},{"q":"Völlige Abwesenheit des Problems wird nicht als Ziel dargestellt.","a":0}]},"part2":{"title":"Bölüm 2 · Uzman röportajı","plays":2,"script":"Moderatorin: Herr Neumann, viele Menschen glauben, Multitasking spare Zeit. Stimmt das? Experte: Bei einfachen, automatisierten Tätigkeiten können mehrere Prozesse parallel laufen. Bei anspruchsvollen Denkaufgaben wechseln wir jedoch meist schnell zwischen Aufgaben. Dieser Wechsel kostet Zeit und erhöht die Fehlerquote. Moderatorin: Ist das bei jungen Menschen anders? Experte: Sie sind oft an häufige Unterbrechungen gewöhnt, aber Gewöhnung bedeutet nicht automatisch bessere Leistung. In unseren Studien sehen wir eher, dass Personen ihre eigene Effizienz überschätzen. Moderatorin: Hilft es, Benachrichtigungen auszuschalten? Experte: Ja, allerdings reicht das allein nicht. Wer ständig erwartet, dass eine Nachricht kommen könnte, bleibt innerlich aufmerksam für mögliche Unterbrechungen. Sinnvoll sind deshalb klar definierte Phasen, in denen Kommunikationskanäle geschlossen werden. Moderatorin: Manche Unternehmen führen Fokuszeiten ein. Experte: Das kann funktionieren, wenn die Organisation es ernst meint. Es bringt wenig, zwei Stunden als Fokuszeit zu deklarieren und gleichzeitig schnelle Antworten zu erwarten. Moderatorin: Gibt es Tätigkeiten, bei denen Unterbrechungen sogar nützlich sind? Experte: Bei kreativen Problemen kann eine Pause helfen. Das ist aber etwas anderes als eine zufällige Nachricht. Eine bewusst gewählte Unterbrechung kann Distanz schaffen; unvorhersehbare Unterbrechungen fragmentieren eher die Aufmerksamkeit.","items":[{"q":"Bei komplexen Aufgaben erledigt das Gehirn mehrere Denkprozesse gleichzeitig.","a":1},{"q":"Häufiger Aufgabenwechsel kann die Fehlerquote erhöhen.","a":0},{"q":"Jüngere Menschen sind nachweislich effizienter im Multitasking.","a":1},{"q":"Menschen überschätzen laut Experte teilweise ihre Multitasking-Leistung.","a":0},{"q":"Ausgeschaltete Benachrichtigungen lösen das Problem vollständig.","a":1},{"q":"Fokuszeiten funktionieren nur, wenn Erwartungen im Unternehmen dazu passen.","a":0},{"q":"Der Experte empfiehlt Fokuszeiten von genau zwei Stunden.","a":2},{"q":"Bewusste Pausen können bei kreativen Problemen hilfreich sein.","a":0},{"q":"Jede Form von Unterbrechung wirkt gleich auf Aufmerksamkeit.","a":1}],"labels":["stimmt","stimmt nicht","dazu wird nichts gesagt"]},"part3":{"title":"Bölüm 3 · Tartışma","plays":1,"segments":[{"script":"Moderator: Sollten Innenstädte komplett autofrei werden? Stadtplanerin: Ein vollständiges Verbot klingt einfach, ignoriert aber Lieferverkehr und Menschen mit eingeschränkter Mobilität. Ich plädiere für deutlich weniger privaten Autoverkehr, aber mit klar definierten Ausnahmen. Händler: Mein Hauptproblem ist nicht die Reduktion an sich, sondern die Planbarkeit. Wenn Regeln ständig wechseln, können Betriebe Logistik kaum organisieren.","items":[{"q":"Was fordert die Stadtplanerin?","o":["Ein ausnahmsloses Verbot","Weniger privaten Autoverkehr mit Ausnahmen","Mehr Parkplätze"],"a":1},{"q":"Was kritisiert der Händler vor allem?","o":["Unklare und wechselnde Regeln","Zu viele Fahrräder","Zu wenig Lieferverkehr"],"a":0}]},{"script":"Moderator: Häufig heißt es, weniger Autos machten Zentren automatisch attraktiver. Händler: Das kann stimmen, wenn gleichzeitig gute Erreichbarkeit geschaffen wird. Wer nur Parkplätze entfernt, ohne ÖPNV und Lieferzonen zu verbessern, verlagert Probleme. Stadtplanerin: Genau deshalb müssen Maßnahmen als Paket geplant werden. Aufenthaltsqualität entsteht nicht durch Verbote allein.","items":[{"q":"Wovon hängt Attraktivität laut Händler ab?","o":["Nur von weniger Parkplätzen","Von alternativer Erreichbarkeit und Logistik","Von höheren Mieten"],"a":1},{"q":"Worin sind sich beide einig?","o":["Einzelmaßnahmen reichen nicht","Autos müssen unverändert bleiben","ÖPNV spielt keine Rolle"],"a":0}]},{"script":"Moderator: Wie reagieren Bewohner? Stadtplanerin: Am Anfang gibt es oft Widerstand, weil Menschen Verluste stärker wahrnehmen als mögliche Gewinne. Nach Umbauten steigt die Zustimmung häufig, wenn der öffentliche Raum tatsächlich besser nutzbar wird. Händler: Erfahrungen aus anderen Städten sind hilfreich, aber sie lassen sich nicht eins zu eins übertragen.","items":[{"q":"Wie erklärt die Stadtplanerin anfänglichen Widerstand?","o":["Menschen gewichten Verluste stark","Alle sind gegen Veränderungen","Es fehlen Daten"],"a":0},{"q":"Was sagt der Händler zu anderen Städten?","o":["Erfahrungen sind wertlos","Modelle müssen an lokale Bedingungen angepasst werden","Man soll alles kopieren"],"a":1}]},{"script":"Moderator: Was wäre ein vernünftiger nächster Schritt? Händler: Pilotzonen mit klaren Messkriterien. Dann kann man sehen, wie sich Umsätze, Lieferzeiten und Besucherzahlen entwickeln. Stadtplanerin: Dem stimme ich zu. Zusätzlich würde ich Luftqualität und Aufenthaltsdauer messen. Entscheidungen sollten danach auf mehreren Kriterien beruhen, nicht nur auf Verkehrszahlen.","items":[{"q":"Was schlägt der Händler vor?","o":["Sofortiges dauerhaftes Verbot","Pilotzonen mit Messkriterien","Keine Veränderung"],"a":1},{"q":"Was ergänzt die Stadtplanerin?","o":["Weitere Qualitätsindikatoren","Nur Verkehrszahlen zählen","Keine Messung nötig"],"a":0}]}]},"part4":{"title":"Bölüm 4 · Sunum","plays":2,"script":"Sehr geehrte Damen und Herren, ich möchte heute über Bürgerwissenschaft, auch Citizen Science genannt, sprechen. Gemeint sind Forschungsprojekte, an denen Menschen ohne professionelle wissenschaftliche Ausbildung aktiv mitwirken. Besonders bekannt sind Projekte zur Beobachtung von Vögeln, Insekten oder Wetterphänomenen. Der größte Vorteil liegt in der räumlichen und zeitlichen Reichweite: Ein kleines Forschungsteam könnte unmöglich gleichzeitig Daten aus Tausenden Orten sammeln. Freiwillige können diese Lücke schließen. Allerdings entstehen neue methodische Fragen. Wenn viele Personen Daten erfassen, unterscheiden sich Erfahrung und Genauigkeit. Gute Projekte reagieren darauf mit klaren Protokollen, Schulungen und automatischen Plausibilitätsprüfungen. Ein zweiter Punkt betrifft Motivation. Teilnehmende bleiben eher langfristig aktiv, wenn sie erfahren, wozu ihre Daten beitragen. Deshalb veröffentlichen erfolgreiche Projekte Zwischenergebnisse und erklären, wie einzelne Beobachtungen in größere Analysen einfließen. Bürgerwissenschaft ersetzt professionelle Forschung nicht. Sie erweitert vielmehr die Datengrundlage und kann Themen sichtbar machen, die sonst wenig Aufmerksamkeit erhalten. Gleichzeitig entsteht ein gesellschaftlicher Effekt: Wer selbst Daten erhebt, entwickelt oft ein genaueres Verständnis dafür, wie wissenschaftliche Erkenntnisse zustande kommen – einschließlich Unsicherheit, Fehlern und notwendigen Kontrollen. Damit Citizen Science zuverlässig funktioniert, müssen Aufgaben jedoch so gestaltet sein, dass sie ohne Spezialgeräte und mit vertretbarem Aufwand durchgeführt werden können. Besonders komplexe Messungen bleiben daher Fachleuten vorbehalten. Die Zukunft liegt vermutlich in hybriden Modellen, in denen große Freiwilligennetze mit professionellen Laboren und digitalen Prüfverfahren zusammenarbeiten.","items":[{"q":"Was ist ein Hauptvorteil von Citizen Science?","o":["Forschung wird ohne Fachleute möglich","Große räumliche und zeitliche Datenerfassung","Jede Messung wird genauer"],"a":1},{"q":"Welches Problem entsteht durch viele Freiwillige?","o":["Unterschiedliche Datengenauigkeit","Zu wenige Orte","Keine Motivation von Forschern"],"a":0},{"q":"Wie sichern gute Projekte Qualität?","o":["Sie verzichten auf Regeln","Durch Protokolle, Schulung und Plausibilitätsprüfungen","Nur durch Bezahlung"],"a":1},{"q":"Was stärkt langfristige Motivation?","o":["Wenn Ergebnisse und Nutzen sichtbar werden","Wenn Daten geheim bleiben","Wenn Aufgaben schwieriger werden"],"a":0},{"q":"Wie wird Citizen Science im Vortrag eingeordnet?","o":["Als Ersatz professioneller Forschung","Als Ergänzung professioneller Forschung","Als reine Bildungsmaßnahme"],"a":1},{"q":"Welchen gesellschaftlichen Effekt nennt der Vortrag?","o":["Mehr Verständnis für wissenschaftliche Prozesse","Weniger Interesse an Wissenschaft","Sichere Beseitigung aller Unsicherheit"],"a":0},{"q":"Was bleibt eher Fachleuten vorbehalten?","o":["Einfache Beobachtungen","Komplexe Messungen mit Spezialanforderungen","Das Lesen von Zwischenergebnissen"],"a":1}]}},"writing":{"forum":{"id":"mock-w1","title":"Künstliche Intelligenz in der Hochschullehre","prompt":"Sie schreiben einen Diskussionsbeitrag in einem Hochschulforum. Diskutieren Sie, wie der Einsatz generativer künstlicher Intelligenz an Hochschulen geregelt werden sollte.","points":["Erläutern Sie eine Chance.","Begründen Sie ein Risiko.","Veranschaulichen Sie Ihre Argumentation an einem konkreten Beispiel.","Machen Sie einen Vorschlag für sinnvolle Regeln."],"target":230,"model":""},"email":{"id":"mock-w2","title":"Arbeitsraum in der Bibliothek","prompt":"Sie haben in der Universitätsbibliothek wiederholt einen als ruhig ausgewiesenen Arbeitsraum reserviert. Der Raum wird jedoch regelmäßig für laute Gruppentreffen genutzt. Schreiben Sie an die Bibliotheksleitung.","points":["Machen Sie auf das Problem aufmerksam.","Beschreiben Sie die Auswirkungen auf Ihre Arbeit.","Schlagen Sie eine konkrete Lösung vor.","Bitten Sie höflich um eine zeitnahe Reaktion."],"target":120,"model":""}},"speaking":{"presentation":{"id":"mock-sp1","title":"Künstliche Intelligenz an Hochschulen","intro":"Sie nehmen an einem Seminar zu aktuellen Fragen teil und halten einen kurzen Vortrag über generative künstliche Intelligenz in der Hochschullehre.","points":["Geben Sie ein konkretes Anwendungsbeispiel.","Vergleichen Sie eine Chance und ein Risiko.","Erläutern Sie, welche Regeln Sie für notwendig halten.","Schließen Sie mit Ihrer eigenen Bewertung."],"questions":["Welche Kompetenz sollten Studierende im Umgang mit KI unbedingt lernen?","Wo würden Sie eine klare Grenze für den Einsatz ziehen?"]},"discussion":{"id":"mock-sd1","title":"Autoverkehr im Stadtzentrum","input":"Eine Stadt plant, den privaten Autoverkehr im Zentrum innerhalb von fünf Jahren deutlich zu reduzieren.","points":["Umwelt- und Gesundheitswirkungen","Erreichbarkeit und lokale Wirtschaft","Alternativen zum privaten Auto","Prioritäten für einen tragfähigen Kompromiss"]}}},"telc":{"overview":[{"name":"Okuduğunu anlama","detail":"90 dk. · Bölüm 1: 6 metin rekonstrüksiyonu · Bölüm 2: 6 seçici okuma · Bölüm 3: 11 doğru/yanlış/metinde yok + 1 başlık","points":48},{"name":"Dil yapıları","detail":"22 adet 4 seçenekli dilbilgisi/kelime sorusu","points":22},{"name":"Ara","detail":"20 dk.","points":0},{"name":"Dinlediğini anlama","detail":"yakl. 40 dk. · 8 genel eşleştirme · 10 ayrıntı sorusu · 10 bilgi aktarımı","points":48},{"name":"Yazılı anlatım","detail":"70 dk. · 2 konudan 1 uzun tartışmacı/görüş bildiren metin","points":48},{"name":"Sözlü anlatım","detail":"20 dk hazırlık + yakl. 16 dk çift sınav · sunum, partner özeti/sorular ve tartışma","points":48}],"reading1":{"text":"Wissenschaftliche Konferenzen galten lange als unverzichtbare Orte der persönlichen Begegnung. Die Erfahrungen mit digitalen Veranstaltungen haben jedoch gezeigt, dass sich manche Funktionen auch online erfolgreich ___(1)___. Besonders für kurze Fachbeiträge und internationale Teilnahme ___(2)___ virtuelle Formate deutliche Vorteile. Gleichzeitig wurde häufig darauf hingewiesen, dass zufällige Begegnungen und informelle Gespräche online schwerer ___(3)___. Viele Einrichtungen versuchen deshalb inzwischen, beide Formate nicht gegeneinander ___(4)___, sondern je nach Ziel zu kombinieren. Damit hybride Veranstaltungen funktionieren, müssen Online-Teilnehmende aktiv in die Diskussion ___(5)___ werden. Andernfalls bleiben sie leicht in einer passiven Zuschauerrolle. Die zentrale Frage der Konferenzplanung lautet künftig daher nicht mehr „digital oder vor Ort?“, sondern welche Funktion in welchem Format am besten ___(6)___ werden kann.","options":[["verbieten lassen","übersehen lassen","erfüllen lassen","absagen lassen"],["bieten","verschließen","bestreiten","verhindern"],["bestanden","ertragen","verloren","entstehen"],["auszugeben","auszuspielen","auszulassen","auszurichten"],["entzogen","umgangen","einbezogen","verschoben"],["erfüllt","vermutet","verschwiegen","vermieden"]],"answers":[2,0,3,1,2,0]},"reading2":{"texts":[{"id":"A","text":"Die Universitätsbibliothek bleibt künftig auch nachts geöffnet. In den unbesetzten Zeiten ist der Zutritt jedoch nur mit Bibliotheksausweis möglich; eine persönliche Beratung wird dann nicht angeboten."},{"id":"B","text":"Ein neuer Forschungsfonds fördert ausschließlich Projekte, an denen mindestens zwei Teams aus unterschiedlichen Fakultäten beteiligt sind. Anträge aus nur einem Fachbereich werden nicht berücksichtigt."},{"id":"C","text":"Das Sprachenzentrum bietet im Sommer einen Intensivkurs Deutsch an. Der Unterricht findet vormittags statt. Für die Anmeldung ist ein B2-Zertifikat oder ein entsprechendes Ergebnis im Einstufungstest erforderlich."},{"id":"D","text":"Das Fahrradverleihsystem auf dem Campus wird erneuert. Die ersten 30 Minuten jeder Fahrt sind kostenlos, längere Nutzungszeiten werden berechnet. Für Studierende und Beschäftigte gelten dieselben Bedingungen."},{"id":"E","text":"Das Career Center bietet Absolventinnen und Absolventen Online-Beratung an. In den ersten zwei Jahren nach dem Abschluss ist dieser Service kostenlos, danach fällt eine Gebühr an."},{"id":"F","text":"Die theoretische Labor-Sicherheitsschulung kann vollständig online absolviert werden. Der praktische Teil muss dagegen persönlich auf dem Campus durchgeführt werden."}],"items":[{"q":"Wer braucht für die Nutzung außerhalb normaler Zeiten eine Karte?","a":"A"},{"q":"Wo ist Zusammenarbeit zwischen Fachbereichen Voraussetzung?","a":"B"},{"q":"Wo muss ein bestimmtes Sprachniveau nachgewiesen werden?","a":"C"},{"q":"Welches Angebot ist nur für kurze Nutzung vollständig kostenlos?","a":"D"},{"q":"Welches Angebot bleibt nach Abschluss nur zeitlich begrenzt gratis?","a":"E"},{"q":"Wo kann ein Teil digital, ein anderer aber nur vor Ort absolviert werden?","a":"F"}]},"reading3":{"text":"Peer-Review-Verfahren sollen wissenschaftliche Qualität sichern, indem Fachkolleginnen und Fachkollegen Manuskripte vor der Veröffentlichung prüfen. Das System ist jedoch nicht einheitlich. Bei manchen Zeitschriften kennen Gutachter die Namen der Autorinnen und Autoren, bei anderen bleiben beide Seiten anonym. Befürworter stärkerer Anonymisierung hoffen, dass institutionelles Prestige oder bekannte Namen weniger Einfluss haben. Vollständige Anonymität lässt sich in kleinen Fachgebieten allerdings oft nicht gewährleisten, weil Thema, Datensatz oder Zitierweise Rückschlüsse zulassen.\n\nKritisiert wird außerdem, dass Gutachten meist unbezahlt erstellt werden. Für Forschende ist diese Arbeit Teil der wissenschaftlichen Selbstverwaltung, konkurriert aber mit Forschung, Lehre und Verwaltung. Einige Verlage experimentieren deshalb mit Anerkennungssystemen, etwa dokumentierten Reviewer-Profilen oder formellen Zertifikaten. Eine direkte Bezahlung ist dagegen umstritten, weil sie neue Interessenkonflikte schaffen könnte.\n\nAuch Geschwindigkeit ist ein Problem. Ein sorgfältiges Gutachten braucht Zeit, während Autorinnen und Autoren Ergebnisse möglichst schnell veröffentlichen möchten. Preprints umgehen diese Verzögerung, indem Manuskripte bereits vor dem Peer Review öffentlich zugänglich gemacht werden. Dadurch kann Wissen schneller zirkulieren, doch die Texte sind zu diesem Zeitpunkt noch nicht formal begutachtet. Leser müssen den Status daher richtig einordnen.\n\nTrotz aller Kritik wird Peer Review nicht einfach als überholt betrachtet. Viele Fachleute sehen vielmehr Reformbedarf: transparentere Kriterien, bessere Anerkennung der Gutachterarbeit und klarere Kennzeichnung unterschiedlicher Veröffentlichungsstadien.","items":[{"q":"Bei allen Zeitschriften bleiben Autor und Gutachter anonym.","a":1},{"q":"Anonymisierung soll den Einfluss bekannter Namen reduzieren.","a":0},{"q":"In kleinen Fachgebieten kann Anonymität schwer sicherzustellen sein.","a":0},{"q":"Der Text nennt eine feste Zahl von Tagen, innerhalb derer jedes Peer-Review abgeschlossen sein muss.","a":2},{"q":"Zertifikate werden als mögliche Anerkennung erprobt.","a":0},{"q":"Direkte Bezahlung ist völlig unumstritten.","a":1},{"q":"Preprints erscheinen erst nach abgeschlossenem Peer Review.","a":1},{"q":"Preprints können Forschung schneller sichtbar machen.","a":0},{"q":"Der Text gibt an, wie hoch die Honorare für Gutachterinnen und Gutachter durchschnittlich sind.","a":2},{"q":"Der Text fordert die vollständige Abschaffung von Peer Review.","a":1},{"q":"Es wird Reformbedarf bei Kriterien und Anerkennung gesehen.","a":0}],"labels":["richtig","falsch","nicht im Text"],"heading":{"q":"Welche Überschrift passt am besten?","o":["Peer Review zwischen Qualitätssicherung und Reformbedarf","Warum wissenschaftliche Zeitschriften verschwinden","Die Geschichte der Universitätsbibliothek"],"a":0}},"languageBlocks":[{"q":"Die Ergebnisse ___ bereits im vergangenen Jahr veröffentlicht ___.","o":["haben / werden","sind / worden","wurden / geworden","sind / geworden"],"a":1,"why":"Perfekt Vorgangspassiv: sein + Partizip II + worden."},{"q":"An der Sitzung ___ ausführlich über die neue Prüfungsordnung diskutiert.","o":["wird worden","hat","ist geworden","wurde"],"a":3,"why":"Unpersönliches Vorgangspassiv."},{"q":"Die Tür ist seit acht Uhr ___.","o":["geschlossen","geschlossen worden","schließen","schloss"],"a":0,"why":"Zustandspassiv: sein + Partizip II."},{"q":"Die Forschenden ___ zu dem Ergebnis, dass weitere Daten nötig sind.","o":["machen","setzen","kommen","führen"],"a":2,"why":"Nomen-Verb-Verbindung: zu dem Ergebnis kommen."},{"q":"Die neue Regelung tritt im Januar in ___.","o":["Gang","Kraft","Folge","Sicht"],"a":1,"why":"Feste Verbindung: in Kraft treten."},{"q":"Die Aussage des Ministers ___ auf heftige Kritik.","o":["stieß","geriet","nahm","setzte"],"a":0,"why":"Feste Verbindung: auf Kritik stoßen."},{"q":"Nach den vorliegenden Daten ___ die Nachfrage in den nächsten Monaten steigen.","o":["soll","will","magst","dürfte"],"a":3,"why":"dürfte = wahrscheinliche Vermutung."},{"q":"Die Ursache ___ in einem technischen Defekt gelegen haben; alle anderen Möglichkeiten wurden ausgeschlossen.","o":["soll","will","muss","kann nur nicht"],"a":2,"why":"muss + Infinitiv Perfekt = starke Schlussfolgerung."},{"q":"Der Konzern ___ bereits seit Monaten von den Problemen gewusst haben. Das berichten mehrere Zeitungen.","o":["soll","muss","will","darf"],"a":0,"why":"soll = Information aus zweiter Hand."},{"q":"Der Zeuge ___ den Vorfall genau beobachtet haben, doch seine Angaben widersprechen sich.","o":["muss","will","darf","sollte"],"a":1,"why":"will = behauptete, vom Sprecher distanzierte Aussage."},{"q":"An Ihrer Stelle ___ ich die Daten vor der Veröffentlichung noch einmal prüfen.","o":["werde","war","wurde","würde"],"a":3,"why":"Konjunktiv II für Rat."},{"q":"Wenn die Finanzierung früher gesichert worden wäre, ___ das Projekt bereits begonnen.","o":["würde","wäre","hätte","sei"],"a":2,"why":"Irrealer Bedingungssatz Vergangenheit: hätte ... begonnen."},{"q":"Der Sprecher erklärte, die Verhandlungen ___ noch nicht abgeschlossen.","o":["sind","seien","wären gewesen","werden"],"a":1,"why":"Konjunktiv I der indirekten Rede."},{"q":"Die Autorin betonte, sie ___ die Daten selbst ausgewertet.","o":["habe","hat","hätte","würde haben"],"a":0,"why":"Indirekte Rede: sie habe ... ausgewertet."},{"q":"___ die Nachfrage stark gestiegen ist, wurde das Angebot erweitert.","o":["Trotz","Wegen","Da","Infolge"],"a":2,"why":"Kausaler Nebensatz mit da."},{"q":"___ des starken Anstiegs der Nachfrage wurde das Angebot erweitert.","o":["Da","Obwohl","Damit","Wegen"],"a":3,"why":"Nominalisierung: wegen + Genitiv."},{"q":"Die Maßnahme ist teuer. ___ könnte sie sich langfristig auszahlen.","o":["Daher","Dennoch","Folglich","Indem"],"a":1,"why":"Dennoch markiert eine Konzession."},{"q":"Die Studie zeigt einen Zusammenhang, ___ sie keine eindeutige Kausalität belegt.","o":["damit","sodass","wobei","deshalb"],"a":2,"why":"wobei kann eine einschränkende Zusatzinformation einleiten."},{"q":"Die Daten wurden anonymisiert, ___ Rückschlüsse auf einzelne Personen verhindert werden.","o":["damit","obwohl","denn","während"],"a":0,"why":"Finalsatz mit damit."},{"q":"Es handelt sich um ein Verfahren, ___ Zuverlässigkeit noch geprüft werden muss.","o":["deren","dem","das","dessen"],"a":3,"why":"Genitiv-Relativpronomen: dessen (Verfahren, Neutrum)."},{"q":"Die Ergebnisse sind nicht nur statistisch signifikant, ___ auch praktisch relevant.","o":["obwohl","sondern","jedoch","denn"],"a":1,"why":"Korrelat: nicht nur ..., sondern auch ..."},{"q":"Je genauer die Kriterien definiert sind, ___ lassen sich die Ergebnisse vergleichen.","o":["so dass besser","obwohl besser","desto besser","damit besser"],"a":2,"why":"Je ..., desto ..."}],"listening1":{"scripts":["Für meine Dissertation brauche ich einen ruhigen Arbeitsplatz. Das neue Großraumbüro ist modern, aber für konzentrierte Analyse ungeeignet.","Ich finde die neue Datenbank grundsätzlich gut, nur die Suchfilter sind so kompliziert, dass ich oft länger brauche als vorher.","Die internationale Summer School war fachlich stark. Besonders wertvoll waren für mich aber die Kontakte zu Forschenden aus anderen Ländern.","Online-Vorlesungen sind praktisch, wenn ich krank bin. Dauerhaft fehlt mir jedoch der direkte Austausch im Seminarraum.","Ich würde gern häufiger mit dem Fahrrad kommen, doch es gibt zu wenige sichere Abstellplätze am Campus.","Die Mensa hat mehr vegane Angebote als früher. Leider sind die Warteschlangen zwischen zwölf und eins inzwischen extrem lang.","Das Schreibzentrum hat mir nicht den Text korrigiert, sondern gezeigt, wie ich meine Argumentation selbst überarbeiten kann. Genau das war hilfreich.","Für den Statistik-Kurs wäre eine kurze Wiederholung der Grundlagen sinnvoll. Viele steigen direkt mit komplexer Software ein und verlieren den Anschluss."],"options":["A Ruhiger Arbeitsplatz fehlt","B Suchsystem schwer bedienbar","C Internationale Kontakte besonders wertvoll","D Präsenz-Austausch bleibt wichtig","E Fahrradinfrastruktur unzureichend","F Lange Wartezeit beim Essen","G Beratung fördert selbstständiges Überarbeiten","H Grundlagen fehlen","I Mehr Prüfungen gewünscht","J Wohnheim zu teuer"],"answers":[0,1,2,3,4,5,6,7]},"listening2":{"script":"Moderator: Frau Stein, Universitäten sprechen viel über interdisziplinäre Forschung. Warum ist sie so schwierig? Expertin: Weil Disziplinen nicht nur unterschiedliche Themen haben, sondern auch unterschiedliche Qualitätskriterien, Methoden und sogar Vorstellungen davon, was als überzeugender Beleg gilt. Moderator: Reicht es, Forschende aus zwei Fächern in ein Projekt zu setzen? Expertin: Nein. Wenn Rollen und Begriffe nicht früh geklärt werden, arbeiten Teams oft parallel statt gemeinsam. Erfolgreiche Projekte investieren am Anfang erstaunlich viel Zeit in gemeinsame Sprache. Moderator: Kostet das nicht Effizienz? Expertin: Kurzfristig ja. Langfristig verhindert es Missverständnisse. Ein zweiter Faktor ist Karrierebewertung. Wer interdisziplinär publiziert, findet manchmal schwerer die “richtige” Fachzeitschrift und wird in traditionellen Bewertungssystemen schlechter eingeordnet. Moderator: Was können Universitäten tun? Expertin: Gemeinsame Infrastruktur schaffen, Moderation finanzieren und bei Berufungs- oder Förderentscheidungen interdisziplinäre Beiträge angemessen anerkennen. Moderator: Ist Interdisziplinarität immer besser? Expertin: Nein. Sie ist sinnvoll, wenn die Forschungsfrage tatsächlich mehrere Perspektiven braucht. Ein Projekt wird nicht automatisch gut, nur weil viele Disziplinen beteiligt sind.","items":[{"q":"Warum ist interdisziplinäre Zusammenarbeit laut Stein anspruchsvoll?","o":["Weil Fächer unterschiedliche Methoden und Gütekriterien haben","Weil Forschende nicht kommunizieren dürfen","Weil nur zwei Fächer erlaubt sind"],"a":0},{"q":"Was reicht nicht aus?","o":["Gemeinsame Begriffe zu entwickeln","Menschen aus mehreren Fächern zusammenzusetzen","Rollen früh zu klären"],"a":1},{"q":"Wofür investieren erfolgreiche Teams am Anfang Zeit?","o":["Für gemeinsame Sprache und Begriffe","Nur für Budgetplanung","Für Publikation nach Projektende"],"a":0},{"q":"Wie bewertet Stein diese Anfangsinvestition?","o":["Kurzfristig aufwendig, langfristig nützlich","Völlig unnötig","Nur für große Unternehmen wichtig"],"a":0},{"q":"Welches Karriereproblem nennt sie?","o":["Interdisziplinäre Arbeit passt schlecht in traditionelle Bewertung","Es gibt zu viele Professuren","Publikationen sind verboten"],"a":0},{"q":"Was können Universitäten finanzieren?","o":["Moderation und gemeinsame Infrastruktur","Nur Einzelbüros","Private Reisen ohne Bezug"],"a":0},{"q":"Was soll bei Entscheidungen anerkannt werden?","o":["Interdisziplinäre Beiträge","Nur Anzahl der Arbeitsstunden","Alter der Forschenden"],"a":0},{"q":"Ist Interdisziplinarität immer überlegen?","o":["Ja","Nein","Nur im ersten Projektjahr"],"a":1},{"q":"Wann ist sie besonders sinnvoll?","o":["Wenn die Frage mehrere Perspektiven erfordert","Wenn ein Projekt wenig Zeit hat","Wenn keine Methode vorhanden ist"],"a":0},{"q":"Was macht ein Projekt laut Stein nicht automatisch gut?","o":["Viele beteiligte Disziplinen","Klare Begriffe","Passende Forschungsfrage"],"a":0}]},"listening3":{"script":"In meinem Vortrag geht es um wissenschaftliches Schreiben als Prozess. Erstens sollte die Fragestellung vor der eigentlichen Textproduktion präzisiert werden. Eine zu breite Frage führt fast zwangsläufig zu einem oberflächlichen Text. Zweitens lohnt es sich, Literatur nicht nur nach Themen, sondern nach Funktion zu ordnen: Welche Quelle liefert Theorie, welche Methode, welche Gegenposition? Drittens empfehle ich, eine Arbeitsgliederung früh anzulegen, sie aber nicht als unveränderlich zu behandeln. Beim Schreiben entstehen neue Zusammenhänge, die eine Umstrukturierung sinnvoll machen können. Viertens sollte die Überarbeitung in mehreren Durchgängen erfolgen. Inhaltliche Logik, Absatzstruktur und sprachliche Korrektheit sind unterschiedliche Ebenen; wer alles gleichzeitig korrigieren will, übersieht leicht Probleme. Fünftens ist Feedback besonders nützlich, wenn die schreibende Person konkrete Fragen stellt. “Ist der Text gut?” führt selten zu hilfreichen Antworten. “Ist die Verbindung zwischen Abschnitt zwei und drei nachvollziehbar?” ist wesentlich produktiver. Schließlich gehört Quellenmanagement von Beginn an zum Prozess. Fehlende Seitenzahlen oder unklare Dateinamen kurz vor der Abgabe zu rekonstruieren kostet unnötig Zeit.","items":[{"q":"1. Vor dem Schreiben soll die ______ präzisiert werden.","answers":["Fragestellung","Forschungsfrage"]},{"q":"2. Literatur kann nach ihrer ______ im Text geordnet werden.","answers":["Funktion","Rolle"]},{"q":"3. Eine frühe Gliederung soll nicht als ______ betrachtet werden.","answers":["unveränderlich","starr"]},{"q":"4. Neue Zusammenhänge können eine ______ nötig machen.","answers":["Umstrukturierung","Neustrukturierung"]},{"q":"5. Überarbeitung sollte in mehreren ______ erfolgen.","answers":["Durchgängen","Schritten"]},{"q":"6. Logik, Absatzstruktur und Sprache sind unterschiedliche ______.","answers":["Ebenen"]},{"q":"7. Für gutes Feedback sollte man ______ Fragen stellen.","answers":["konkrete","präzise"]},{"q":"8. Die Verbindung zwischen Abschnitten ist ein Beispiel für eine ______ Feedbackfrage.","answers":["konkrete","präzise"]},{"q":"9. Quellenmanagement soll von ______ an erfolgen.","answers":["Beginn","Anfang"]},{"q":"10. Fehlende Seitenzahlen kurz vor Abgabe kosten unnötig ______.","answers":["Zeit"]}]},"writingPrompts":[{"title":"Digitale Lehrmaterialien an Hochschulen","prompt":"Erörtern Sie, ob Hochschulen gedruckte Pflichtmaterialien weitgehend durch digitale Materialien ersetzen sollten. Berücksichtigen Sie Lernqualität, Kosten/Zugang, Nachhaltigkeit und Ihre eigene Position."},{"title":"Bewertung wissenschaftlicher Leistung","prompt":"Nehmen Sie Stellung dazu, ob wissenschaftliche Leistung stärker nach gesellschaftlicher Wirkung statt nach Publikationszahlen bewertet werden sollte. Gehen Sie auf Chancen, Probleme, Beispiele und eine mögliche Lösung ein."}],"speaking":{"presentationTopics":["Sollten Vorlesungen grundsätzlich aufgezeichnet werden?","Wie verändert künstliche Intelligenz wissenschaftliches Arbeiten?"],"summaryGuide":"Fassen Sie die Präsentation Ihres Partners bzw. Ihrer Partnerin in etwa 30–60 Sekunden zusammen: Hauptthese, zwei wesentliche Punkte und Schluss. Stellen Sie anschließend mindestens eine passende Anschlussfrage.","discussionQuote":"„Eine Universität sollte nicht Wissen vermitteln, sondern vor allem lehren, wie man Wissen kritisch prüft.“","discussionPoints":["Erläutern Sie das Zitat.","Begründen Sie, in welchen Punkten Sie zustimmen oder widersprechen.","Führen Sie ein konkretes Beispiel an.","Formulieren Sie eine gemeinsame Schlussfolgerung oder eine klare Differenz."]}}};
